/* Organic Chemistry, source scan p.219–258; four theory pages missing. See docs/organic-coverage.md. */
const ALL_TOPICS=[{"id": "carbon", "name": "Carbon, bonds and representations", "ref": "p.220, 222, 246"}, {"id": "series", "name": "Homologous series and family formulae", "ref": "p.221, 227"}, {"id": "groups", "name": "Functional groups and common names", "ref": "p.222, 226"}, {"id": "naming", "name": "IUPAC: structure → name and name → structure", "ref": "p.224–226, 247–248"}, {"id": "isomers", "name": "Chain and position isomerism", "ref": "p.223, 247–248"}, {"id": "alkanes", "name": "Methane and ethane: preparation and reactions", "ref": "p.228–231, 249"}, {"id": "alkenes", "name": "Ethene: elimination, addition and polymerisation", "ref": "p.232–233, 250"}, {"id": "alkynes", "name": "Ethyne: preparation and two-stage addition", "ref": "p.236–239, 251"}, {"id": "alcohol", "name": "Ethanol: hydrolysis, oxidation and dehydration", "ref": "p.240–241, 252"}, {"id": "acid", "name": "Ethanoic acid and esterification", "ref": "p.244–245, 252"}, {"id": "tests", "name": "Observations, distinguishing tests and uses", "ref": "p.249–252"}, {"id": "drawing", "name": "Draw structures and mark functional groups", "ref": "p.226, 247–248"}];
const CONCEPT={"carbon": "<h3>Start by checking bonds, not memorising names</h3><p>Carbon has electronic configuration 2,4. It forms four covalent bonds.</p><p>Count a double bond twice. Count a triple bond three times.</p><div class=\"exam\">★ <b>Learn this exactly:</b> Catenation — Tendency of an element to form chains of identical atoms.</div><p>Strong carbon–carbon bonds permit straight, branched and closed chains.</p><p>Organic chemistry studies specific carbon compounds. Carbon oxides, carbonates, bicarbonates and metallic carbides are treated as inorganic.</p><table class=\"cmp\"><tr><th>Representation</th><th>What it tells you</th></tr><tr><td>Molecular formula</td><td>How many atoms of each element occur. C₂H₆ says two C and six H.</td></tr><tr><td>Structural formula</td><td>How atoms connect. CH₃–CH₃ shows the carbon–carbon bond.</td></tr><tr><td>Expanded structure</td><td>Each hydrogen and every bond are visible.</td></tr></table><figure style=\"margin:12px 0\"><img src=\"../assets/organic/ethane.svg\" alt=\"Expanded structural formula of ethane\" style=\"display:block;max-width:100%;height:auto\" loading=\"lazy\"><figcaption>ethane · Every bond is shown. Check four bonds at each carbon.</figcaption></figure><figure style=\"margin:12px 0\"><img src=\"../assets/organic/ethene.svg\" alt=\"Expanded structural formula of ethene\" style=\"display:block;max-width:100%;height:auto\" loading=\"lazy\"><figcaption>ethene · Every bond is shown. Check four bonds at each carbon.</figcaption></figure><figure style=\"margin:12px 0\"><img src=\"../assets/organic/ethyne.svg\" alt=\"Expanded structural formula of ethyne\" style=\"display:block;max-width:100%;height:auto\" loading=\"lazy\"><figcaption>ethyne · Every bond is shown. Check four bonds at each carbon.</figcaption></figure><table class=\"cmp\"><tr><th>Question</th><th>Answer</th></tr><tr><td>Why does ethene have fewer hydrogens than ethane?</td><td>The double bond uses two of each carbon’s four valencies. Each carbon therefore bonds to two hydrogens.</td></tr><tr><td>Why not give carbon five bonds?</td><td>Carbon is tetravalent in these compounds. The sum of its bond orders must be four.</td></tr><tr><td>Why can one molecular formula describe different compounds?</td><td>The same atoms can connect differently. Molecular formula does not specify connectivity.</td></tr></table><p>Open-chain compounds are aliphatic. Benzene is the cyclic example required by this source.</p><p>Benzene has six carbons in a ring, alternating double bonds in the school representation, and formula C₆H₆.</p><p>Wohler synthesised urea in 1828. This contradicted the vital-force theory.</p><table class=\"cmp\"><tr><th>Typical organic compound</th><th>Typical ionic inorganic compound</th></tr><tr><td>Covalent; often low melting and boiling points</td><td>Ionic; often high melting and boiling points</td></tr><tr><td>Often soluble in organic solvents; often poorly soluble in water</td><td>Often soluble in water</td></tr><tr><td>Usually poor electrical conductor</td><td>Conducts in molten or aqueous state, not as an ionic solid</td></tr></table><p>These comparisons are generalisations. Ethanol and ethanoic acid are water-soluble organic examples.</p>", "series": "<h3>One family pattern replaces many separate facts</h3><div class=\"exam\">★ <b>Learn this exactly:</b> A series of organic compounds which follow a regular structural pattern, in which the successive compounds differing by a ‘CH₂ group’.</div><p>Members share a functional group and general formula. Their chemical properties are similar.</p><p>Adjacent members differ by CH₂. Their relative molecular masses differ by 14.</p><p>Physical properties change gradually. Boiling point generally increases with molecular mass.</p><table class=\"cmp\"><tr><th>Family</th><th>General formula</th><th>First three members</th></tr><tr><td>Alkanes</td><td>CₙH₂ₙ₊₂, n ≥ 1</td><td>CH₄, C₂H₆, C₃H₈</td></tr><tr><td>Alkenes</td><td>CₙH₂ₙ, n ≥ 2</td><td>C₂H₄, C₃H₆, C₄H₈</td></tr><tr><td>Alkynes</td><td>CₙH₂ₙ₋₂, n ≥ 2</td><td>C₂H₂, C₃H₄, C₄H₆</td></tr><tr><td>Monohydric alcohols</td><td>CₙH₂ₙ₊₁OH</td><td>CH₃OH, C₂H₅OH, C₃H₇OH</td></tr></table><table class=\"cmp\"><tr><th>Question</th><th>Answer</th></tr><tr><td>Why is there no methene or methyne?</td><td>A carbon–carbon double or triple bond requires at least two carbon atoms.</td></tr><tr><td>Why do similar chemical properties recur?</td><td>Each member has the same functional group.</td></tr><tr><td>Why not identify every family from molecular formula alone?</td><td>Different structures can share a formula. CₙH₂ₙ can also describe a cycloalkane. Use the stated open-chain context.</td></tr></table><p>Relative molecular mass: multiply each atom count by its relative atomic mass. Add the results.</p><p>For C₅H₁₂: Mᵣ = 5 × 12 + 12 × 1 = 72. Vapour density = 72/2 = 36.</p>", "groups": "<h3>Recognise the part that controls the family</h3><div class=\"exam\">★ <b>Learn this exactly:</b> Functional group — An atom, radical or bond which defines the structure of organic compounds &amp; confers characteristic properties to it.</div><table class=\"cmp\"><tr><th>Family</th><th>Structural feature</th><th>Name ending or prefix</th><th>Textbook examples</th></tr><tr><td>Alkene</td><td>C=C</td><td>-ene</td><td>Ethene / ethylene</td></tr><tr><td>Alkyne</td><td>C≡C</td><td>-yne</td><td>Ethyne / acetylene</td></tr><tr><td>Alcohol</td><td>–OH on a saturated carbon</td><td>-ol</td><td>Ethanol / ethyl alcohol</td></tr><tr><td>Aldehyde</td><td>–C(=O)H, written –CHO</td><td>-al</td><td>Ethanal / acetaldehyde</td></tr><tr><td>Carboxylic acid</td><td>–C(=O)OH, written –COOH</td><td>-oic acid</td><td>Ethanoic acid / acetic acid</td></tr><tr><td>Ketone</td><td>–C(=O)– within the chain</td><td>-one</td><td>Propanone / acetone</td></tr><tr><td>Ether</td><td>C–O–C</td><td>alkoxyalkane</td><td>Methoxymethane / dimethyl ether</td></tr><tr><td>Alkyl halide</td><td>–Cl, –Br, –I or –F</td><td>chloro-, bromo-, iodo-, fluoro-</td><td>Bromoethane / ethyl bromide</td></tr><tr><td>Ester</td><td>–C(=O)O–</td><td>alkyl alkanoate</td><td>Ethyl ethanoate / ethyl acetate</td></tr></table><figure style=\"margin:12px 0\"><img src=\"../assets/organic/ethanol.svg\" alt=\"Expanded structural formula of ethanol\" style=\"display:block;max-width:100%;height:auto\" loading=\"lazy\"><figcaption>ethanol · Every bond is shown. Check four bonds at each carbon.</figcaption></figure><figure style=\"margin:12px 0\"><img src=\"../assets/organic/ethanal.svg\" alt=\"Expanded structural formula of ethanal\" style=\"display:block;max-width:100%;height:auto\" loading=\"lazy\"><figcaption>ethanal · Every bond is shown. Check four bonds at each carbon.</figcaption></figure><figure style=\"margin:12px 0\"><img src=\"../assets/organic/ethanoic-acid.svg\" alt=\"Expanded structural formula of ethanoic acid\" style=\"display:block;max-width:100%;height:auto\" loading=\"lazy\"><figcaption>ethanoic acid · Every bond is shown. Check four bonds at each carbon.</figcaption></figure><p>Blue shading marks the characteristic group. In an alkane, there is no separate functional group.</p><p>An alkyl group forms when one H is removed from an alkane: CH₄ → CH₃–, methyl.</p><p>Other examples: ethyl C₂H₅–, propyl C₃H₇–, butyl C₄H₉–, pentyl C₅H₁₁–.</p><table class=\"cmp\"><tr><th>Question</th><th>Answer</th></tr><tr><td>Why is –COOH not simply an alcohol group?</td><td>Its OH belongs to a carboxyl group attached to a carbonyl carbon. The whole group determines acidic properties.</td></tr><tr><td>Why count the carbon in –CHO or –COOH?</td><td>That carbon belongs to the principal carbon chain.</td></tr><tr><td>Why not confuse an ether and an ester?</td><td>Both contain an oxygen bridge. An ester also contains C=O beside that bridge.</td></tr></table>", "naming": "<h3>Structure → name: use the same routine every time</h3><table class=\"cmp\"><tr><th>Carbon count</th><th>Root</th></tr><tr><td>1</td><td>meth-</td></tr><tr><td>2</td><td>eth-</td></tr><tr><td>3</td><td>prop-</td></tr><tr><td>4</td><td>but-</td></tr><tr><td>5</td><td>pent-</td></tr><tr><td>6</td><td>hex-</td></tr><tr><td>7</td><td>hept-</td></tr></table><ol><li>Select the longest continuous chain containing the relevant group or multiple bond.</li><li>Number from the end giving that group or multiple bond the lowest locant.</li><li>Locate each branch and halogen.</li><li>Combine the root, bond ending and functional-group ending.</li><li>Write substituents alphabetically. Use di-, tri- or tetra- for repeated substituents.</li></ol><figure style=\"margin:12px 0\"><img src=\"../assets/organic/4-methylpentan-2-ol.svg\" alt=\"Expanded structural formula of 4-methylpentan-2-ol\" style=\"display:block;max-width:100%;height:auto\" loading=\"lazy\"><figcaption>4-methylpentan-2-ol · Every bond is shown. Check four bonds at each carbon.</figcaption></figure><p>Five carbons give pentan-. The OH gets position 2. The methyl branch is at position 4.</p><p>Answer: 4-methylpentan-2-ol.</p><table class=\"cmp\"><tr><th>Question</th><th>Answer</th></tr><tr><td>Why not number from the methyl end?</td><td>The OH must receive the lower locant. Here its position is 2, not 4.</td></tr><tr><td>Why not select the visually straight horizontal line automatically?</td><td>The longest continuous chain can turn through a branch. Count connected carbons.</td></tr><tr><td>Why repeat the number in 2,2-dimethylpropane?</td><td>Both methyl groups attach to carbon 2. Each needs its locant.</td></tr></table><h3>Name → structure: reverse the routine</h3><ol><li>Draw the parent carbon chain.</li><li>Number the chain.</li><li>Insert the multiple bond or functional group.</li><li>Attach the named branches and halogens.</li><li>Add H atoms until each carbon has four bonds.</li></ol><figure style=\"margin:12px 0\"><img src=\"../assets/organic/2-chloro-3-methylbut-2-ene.svg\" alt=\"Expanded structural formula of 2-chloro-3-methylbut-2-ene\" style=\"display:block;max-width:100%;height:auto\" loading=\"lazy\"><figcaption>2-chloro-3-methylbut-2-ene · Every bond is shown. Check four bonds at each carbon.</figcaption></figure><p>This is the worked name-to-structure example on p.225.</p><p>Use commas between numbers and hyphens between numbers and words.</p><p>Modern names: butane, pentane, propanal, propanoic acid. Their carbon-1 position is implicit.</p><p>The source’s “1-butane”, “1-pentane” and redundant acid or aldehyde locants are unnecessary.</p>", "isomers": "<h3>Same atom counts, different connections</h3><div class=\"exam\">★ <b>Learn this exactly:</b> Isomers are organic compounds having the same molecular formula but differing in molecular arrangement or in structural formula.</div><p>First compare molecular formulae. Then compare the carbon skeleton and group positions.</p><figure style=\"margin:12px 0\"><img src=\"../assets/organic/butane.svg\" alt=\"Expanded structural formula of butane\" style=\"display:block;max-width:100%;height:auto\" loading=\"lazy\"><figcaption>butane · Every bond is shown. Check four bonds at each carbon.</figcaption></figure><figure style=\"margin:12px 0\"><img src=\"../assets/organic/2-methylpropane.svg\" alt=\"Expanded structural formula of 2-methylpropane\" style=\"display:block;max-width:100%;height:auto\" loading=\"lazy\"><figcaption>2-methylpropane · Every bond is shown. Check four bonds at each carbon.</figcaption></figure><p>Both are C₄H₁₀. Different carbon skeletons give chain isomerism.</p><figure style=\"margin:12px 0\"><img src=\"../assets/organic/but-1-ene.svg\" alt=\"Expanded structural formula of but-1-ene\" style=\"display:block;max-width:100%;height:auto\" loading=\"lazy\"><figcaption>but-1-ene · Every bond is shown. Check four bonds at each carbon.</figcaption></figure><figure style=\"margin:12px 0\"><img src=\"../assets/organic/but-2-ene.svg\" alt=\"Expanded structural formula of but-2-ene\" style=\"display:block;max-width:100%;height:auto\" loading=\"lazy\"><figcaption>but-2-ene · Every bond is shown. Check four bonds at each carbon.</figcaption></figure><p>Both are C₄H₈. The same skeleton has its double bond at different positions.</p><p>That difference gives position isomerism.</p><table class=\"cmp\"><tr><th>Question</th><th>Answer</th></tr><tr><td>Why are rotating or reversing a drawing not new isomers?</td><td>The atoms remain connected in the same way.</td></tr><tr><td>Why do isomers within one series have similar chemical properties?</td><td>They have the same functional group. Their different structures can change physical properties.</td></tr><tr><td>Why are ethene and ethane not isomers?</td><td>Their molecular formulae differ: C₂H₄ and C₂H₆.</td></tr></table><p>Butane has two chain isomers. Pentane has three: pentane, 2-methylbutane and 2,2-dimethylpropane.</p><p>The butene structures in scope are but-1-ene, but-2-ene and 2-methylprop-1-ene.</p><p>The cis/trans drawings in the source are reference material. Core practice concerns chain and position isomerism.</p>", "alkanes": "<h3>Alkanes: remove a carboxyl carbon or replace a halogen</h3><p>Alkanes have only single carbon–carbon bonds. Their general formula is CₙH₂ₙ₊₂.</p><p>They are called paraffins because they have comparatively little chemical affinity.</p><p>Methane occurs in natural gas, marsh gas and fire damp. It is a greenhouse gas.</p><p class=\"eq\"><b>CH<sub>3</sub>COONa + NaOH → CH<sub>4</sub> + Na<sub>2</sub>CO<sub>3</sub></b></p><p><b>Conditions:</b> Heat with soda lime (NaOH + CaO).</p><p><b>What changes:</b> Remove the carboxyl carbon. Two-carbon salt gives one-carbon alkane.</p><p class=\"eq\"><b>C<sub>2</sub>H<sub>5</sub>COONa + NaOH → C<sub>2</sub>H<sub>6</sub> + Na<sub>2</sub>CO<sub>3</sub></b></p><p><b>Conditions:</b> Heat with soda lime.</p><p><b>What changes:</b> Three-carbon salt gives two-carbon alkane.</p><p class=\"eq\"><b>CH<sub>3</sub>I + 2[H] → CH<sub>4</sub> + HI</b></p><p><b>Conditions:</b> Zn/Cu couple in alcohol.</p><p><b>What changes:</b> Replace I with H: reduction of an alkyl halide.</p><p class=\"eq\"><b>C<sub>2</sub>H<sub>5</sub>Br + 2[H] → C<sub>2</sub>H<sub>6</sub> + HBr</b></p><p><b>Conditions:</b> Zn/Cu couple in alcohol.</p><p><b>What changes:</b> Replace Br with H.</p><table class=\"cmp\"><tr><th>Question</th><th>Answer</th></tr><tr><td>Why does sodium ethanoate give methane, not ethane?</td><td>The carboxyl carbon is removed as carbonate. Only one carbon remains in the hydrocarbon.</td></tr><tr><td>Why prefer soda lime to NaOH alone?</td><td>Soda lime is not deliquescent and does not attack the glass apparatus as NaOH alone does.</td></tr><tr><td>Why collect methane over water?</td><td>Methane is almost insoluble in water.</td></tr></table><h3>Substitution: replace H, retain the carbon skeleton</h3><p class=\"eq\"><b>CH<sub>4</sub> + Cl<sub>2</sub> → CH<sub>3</sub>Cl + HCl</b></p><p><b>Conditions:</b> Diffused sunlight or ultraviolet light.</p><p><b>What changes:</b> One H is replaced by Cl.</p><p class=\"eq\"><b>CH<sub>4</sub> + 4Cl<sub>2</sub> → CCl<sub>4</sub> + 4HCl</b></p><p><b>Conditions:</b> Excess chlorine, diffused sunlight.</p><p><b>What changes:</b> All four H atoms are replaced.</p><p class=\"eq\"><b>C<sub>2</sub>H<sub>6</sub> + 6Cl<sub>2</sub> → C<sub>2</sub>Cl<sub>6</sub> + 6HCl</b></p><p><b>Conditions:</b> Excess chlorine, diffused sunlight.</p><p><b>What changes:</b> All six H atoms are replaced.</p><p>Successive methane products: CH₃Cl → CH₂Cl₂ → CHCl₃ → CCl₄.</p><p>The products are chloromethane, dichloromethane, trichloromethane and tetrachloromethane.</p><p>Trichloromethane is chloroform. Tetrachloromethane is carbon tetrachloride.</p><h3>Oxidation: conditions decide the product</h3><p class=\"eq\"><b>CH<sub>4</sub> + 2O<sub>2</sub> → CO<sub>2</sub> + 2H<sub>2</sub>O</b></p><p><b>Conditions:</b> Ignite in excess oxygen.</p><p><b>What changes:</b> Complete combustion gives CO2 and water.</p><p class=\"eq\"><b>2C<sub>2</sub>H<sub>6</sub> + 7O<sub>2</sub> → 4CO<sub>2</sub> + 6H<sub>2</sub>O</b></p><p><b>Conditions:</b> Ignite in excess oxygen.</p><p><b>What changes:</b> Balance C, then H, then O.</p><p class=\"eq\"><b>2CH<sub>4</sub> + O<sub>2</sub> → 2CH<sub>3</sub>OH</b></p><p><b>Conditions:</b> Cu catalyst, 200°C, 100 atmospheres (source conditions).</p><p><b>What changes:</b> Controlled catalytic oxidation gives methanol.</p><p class=\"eq\"><b>2C<sub>2</sub>H<sub>6</sub> + O<sub>2</sub> → 2C<sub>2</sub>H<sub>5</sub>OH</b></p><p><b>Conditions:</b> Cu catalyst, 200°C, 100 atmospheres (source conditions).</p><p><b>What changes:</b> Controlled catalytic oxidation gives ethanol.</p><p class=\"eq\"><b>CH<sub>4</sub> + O<sub>2</sub> → HCHO + H<sub>2</sub>O</b></p><p><b>Conditions:</b> Molybdenum oxide catalyst, 350–500°C (source).</p><p><b>What changes:</b> Controlled catalytic oxidation gives methanal.</p><p class=\"eq\"><b>C<sub>2</sub>H<sub>6</sub> + O<sub>2</sub> → CH<sub>3</sub>CHO + H<sub>2</sub>O</b></p><p><b>Conditions:</b> Molybdenum oxide catalyst, 350–500°C (source).</p><p><b>What changes:</b> Controlled catalytic oxidation gives ethanal.</p><p>Limited oxygen can give carbon monoxide. Very limited oxygen can give carbon black.</p><p>2CH₄ + 3O₂ → 2CO + 4H₂O. 2C₂H₆ + 5O₂ → 4CO + 6H₂O.</p><p>2C₂H₆ + 3O₂ → 4C + 6H₂O.</p><p>The source’s direct acidified-dichromate oxidation of an alkane is a schematic pathway, not a standard laboratory preparation.</p><p>Use the specified catalytic conditions for alkane → alcohol. Use acidified dichromate for alcohol → aldehyde → acid.</p><p>Wurtz: 2CH₃I + 2Na → C₂H₆ + 2NaI, dry ether. It does not prepare methane.</p><p>Methane and ethane are colourless, odourless gases. They are nearly insoluble in water.</p>", "alkenes": "<h3>Addition: change C=C to C–C and attach new atoms</h3><figure style=\"margin:12px 0\"><img src=\"../assets/organic/ethene.svg\" alt=\"Expanded structural formula of ethene\" style=\"display:block;max-width:100%;height:auto\" loading=\"lazy\"><figcaption>ethene · Every bond is shown. Check four bonds at each carbon.</figcaption></figure><p class=\"eq\"><b>C<sub>2</sub>H<sub>5</sub>OH → C<sub>2</sub>H<sub>4</sub> + H<sub>2</sub>O</b></p><p><b>Conditions:</b> Conc. H2SO4 at 170°C, or Al2O3 at 350°C.</p><p><b>What changes:</b> Dehydration removes H2O and creates a C=C bond.</p><p class=\"eq\"><b>C<sub>2</sub>H<sub>5</sub>Br + KOH → C<sub>2</sub>H<sub>4</sub> + KBr + H<sub>2</sub>O</b></p><p><b>Conditions:</b> Hot concentrated alcoholic KOH.</p><p><b>What changes:</b> Dehydrohalogenation removes HBr.</p><p class=\"eq\"><b>C<sub>2</sub>H<sub>6</sub> → C<sub>2</sub>H<sub>4</sub> + H<sub>2</sub></b></p><p><b>Conditions:</b> About 500°C, silica–alumina catalyst, absence of air (source).</p><p><b>What changes:</b> Dehydrogenation removes H2.</p><table class=\"cmp\"><tr><th>Question</th><th>Answer</th></tr><tr><td>Why is the temperature 170°C important?</td><td>With concentrated H₂SO₄, this condition favours ethene. The source gives ether formation at 140°C.</td></tr><tr><td>Why alcoholic KOH rather than aqueous KOH?</td><td>Alcoholic KOH favours elimination to ethene. Aqueous KOH favours hydrolysis to ethanol.</td></tr><tr><td>Why pass prepared ethene through NaOH solution?</td><td>It removes acidic impurities, including CO₂ and SO₂.</td></tr></table><p class=\"eq\"><b>C<sub>2</sub>H<sub>4</sub> + H<sub>2</sub> → C<sub>2</sub>H<sub>6</sub></b></p><p><b>Conditions:</b> Nickel catalyst, about 300°C.</p><p><b>What changes:</b> Add one H to each carbon. Double bond becomes single.</p><p class=\"eq\"><b>C<sub>2</sub>H<sub>4</sub> + Cl<sub>2</sub> → C<sub>2</sub>H<sub>4</sub>Cl<sub>2</sub></b></p><p><b>Conditions:</b> Halogen in inert solvent CCl4, room temperature.</p><p><b>What changes:</b> Addition gives a 1,2-dihaloethane.</p><p class=\"eq\"><b>C<sub>2</sub>H<sub>4</sub> + Br<sub>2</sub> → C<sub>2</sub>H<sub>4</sub>Br<sub>2</sub></b></p><p><b>Conditions:</b> Halogen in inert solvent CCl4, room temperature.</p><p><b>What changes:</b> Addition gives a 1,2-dihaloethane.</p><p class=\"eq\"><b>C<sub>2</sub>H<sub>4</sub> + I<sub>2</sub> → C<sub>2</sub>H<sub>4</sub>I<sub>2</sub></b></p><p><b>Conditions:</b> Halogen in inert solvent CCl4, room temperature.</p><p><b>What changes:</b> Addition gives a 1,2-dihaloethane.</p><p class=\"eq\"><b>C<sub>2</sub>H<sub>4</sub> + HBr → C<sub>2</sub>H<sub>5</sub>Br</b></p><p><b>Conditions:</b> Room temperature (source).</p><p><b>What changes:</b> Hydrogen halide adds across the double bond.</p><p class=\"eq\"><b>C<sub>2</sub>H<sub>4</sub> + HCl → C<sub>2</sub>H<sub>5</sub>Cl</b></p><p><b>Conditions:</b> Room temperature (source).</p><p><b>What changes:</b> Hydrogen halide adds across the double bond.</p><p>Alkenes are called olefins: they form oily addition products with halogens.</p><p>They react readily at the multiple bond. Do not draw a carbon with five bonds after addition.</p><p>Cold dilute alkaline KMnO₄ oxidises ethene to ethane-1,2-diol: C₂H₄ + H₂O + [O] → C₂H₆O₂.</p><p>Ethene + ozone gives ethylene ozonide. This appears in the summary as reference chemistry.</p><p>Polymerisation joins many ethene molecules: n CH₂=CH₂ → (–CH₂–CH₂–)ₙ.</p><p>The source specifies high temperature, high pressure and a catalyst.</p><p>Ethene is colourless, slightly soluble in water and slightly lighter than air.</p><p>It is obtained by cracking petroleum hydrocarbons. It is used to ripen fruit and make polyethylene.</p>", "alkynes": "<h3>Two additions can turn C≡C into C–C</h3><figure style=\"margin:12px 0\"><img src=\"../assets/organic/ethyne.svg\" alt=\"Expanded structural formula of ethyne\" style=\"display:block;max-width:100%;height:auto\" loading=\"lazy\"><figcaption>ethyne · Every bond is shown. Check four bonds at each carbon.</figcaption></figure><p class=\"eq\"><b>CaC<sub>2</sub> + 2H<sub>2</sub>O → C<sub>2</sub>H<sub>2</sub> + Ca(OH)<sub>2</sub></b></p><p><b>Conditions:</b> Add cold water dropwise at room temperature.</p><p><b>What changes:</b> Calcium carbide releases ethyne on reaction with water.</p><p class=\"eq\"><b>C<sub>2</sub>H<sub>4</sub>Br<sub>2</sub> + 2KOH → C<sub>2</sub>H<sub>2</sub> + 2KBr + 2H<sub>2</sub>O</b></p><p><b>Conditions:</b> Heat with concentrated alcoholic KOH (textbook route).</p><p><b>What changes:</b> Two HBr units are eliminated.</p><p class=\"eq\"><b>2CH<sub>4</sub> → C<sub>2</sub>H<sub>2</sub> + 3H<sub>2</sub></b></p><p><b>Conditions:</b> About 1500°C, electric arc, absence of air.</p><p><b>What changes:</b> Pyrolysis removes hydrogen and forms ethyne.</p><table class=\"cmp\"><tr><th>Question</th><th>Answer</th></tr><tr><td>Why add cold water dropwise to calcium carbide?</td><td>The reaction gives out heat. Gradual addition controls gas evolution.</td></tr><tr><td>Why collect ethyne over water?</td><td>It is only very slightly soluble in water.</td></tr><tr><td>Why distinguish one stage from two?</td><td>One addition gives an alkene. A second gives an alkane.</td></tr></table><p class=\"eq\"><b>C<sub>2</sub>H<sub>2</sub> + H<sub>2</sub> → C<sub>2</sub>H<sub>4</sub></b></p><p><b>Conditions:</b> Controlled partial hydrogenation. The source shows Ni and limited H2.</p><p><b>What changes:</b> One stage: triple bond becomes double. Continued reaction gives ethane.</p><p class=\"eq\"><b>C<sub>2</sub>H<sub>2</sub> + 2H<sub>2</sub> → C<sub>2</sub>H<sub>6</sub></b></p><p><b>Conditions:</b> Ni, about 300°C, excess hydrogen.</p><p><b>What changes:</b> Two stages add four H atoms.</p><p class=\"eq\"><b>C<sub>2</sub>H<sub>2</sub> + Cl<sub>2</sub> → C<sub>2</sub>H<sub>2</sub>Cl<sub>2</sub></b></p><p><b>Conditions:</b> Room temperature. Iodine addition is difficult (source).</p><p><b>What changes:</b> First stage gives a 1,2-dihaloethene.</p><p class=\"eq\"><b>C<sub>2</sub>H<sub>2</sub> + 2Cl<sub>2</sub> → C<sub>2</sub>H<sub>2</sub>Cl<sub>4</sub></b></p><p><b>Conditions:</b> Excess halogen in inert solvent CCl4.</p><p><b>What changes:</b> Two stages give 1,1,2,2-tetrahaloethane.</p><p class=\"eq\"><b>C<sub>2</sub>H<sub>2</sub> + Br<sub>2</sub> → C<sub>2</sub>H<sub>2</sub>Br<sub>2</sub></b></p><p><b>Conditions:</b> Room temperature. Iodine addition is difficult (source).</p><p><b>What changes:</b> First stage gives a 1,2-dihaloethene.</p><p class=\"eq\"><b>C<sub>2</sub>H<sub>2</sub> + 2Br<sub>2</sub> → C<sub>2</sub>H<sub>2</sub>Br<sub>4</sub></b></p><p><b>Conditions:</b> Excess halogen in inert solvent CCl4.</p><p><b>What changes:</b> Two stages give 1,1,2,2-tetrahaloethane.</p><p class=\"eq\"><b>C<sub>2</sub>H<sub>2</sub> + I<sub>2</sub> → C<sub>2</sub>H<sub>2</sub>I<sub>2</sub></b></p><p><b>Conditions:</b> Room temperature. Iodine addition is difficult (source).</p><p><b>What changes:</b> First stage gives a 1,2-dihaloethene.</p><p class=\"eq\"><b>C<sub>2</sub>H<sub>2</sub> + 2HBr → C<sub>2</sub>H<sub>4</sub>Br<sub>2</sub></b></p><p><b>Conditions:</b> Two successive additions, room temperature (source).</p><p><b>What changes:</b> Final product is 1,1-dihaloethane.</p><p class=\"eq\"><b>C<sub>2</sub>H<sub>2</sub> + 2HCl → C<sub>2</sub>H<sub>4</sub>Cl<sub>2</sub></b></p><p><b>Conditions:</b> Two successive additions, room temperature (source).</p><p><b>What changes:</b> Final product is 1,1-dihaloethane.</p><p>Ethyne is colourless. Impurities cause the characteristic garlic-like odour of commercial acetylene.</p><p>The source purification sequence uses water, then acidified K₂Cr₂O₇ to remove phosphine.</p><p>Ethyne burns: 2C₂H₂ + 5O₂ → 4CO₂ + 2H₂O.</p><p>Cold dilute alkaline KMnO₄ oxidises ethyne: C₂H₂ + 4[O] → (COOH)₂.</p><p>Ozonolysis produces an ozonide, then glyoxal, as reference material in the source.</p><p>The book’s double elimination using alcoholic KOH is an exam route. Full laboratory conversion normally requires stronger conditions.</p><p>The book’s statement that alkynes are always more reactive than alkenes is an oversimplification.</p><p>Core rule: both react at their multiple bonds. Exact relative reactivity depends on the reaction.</p>", "alcohol": "<h3>One reagent choice changes the reaction path</h3><figure style=\"margin:12px 0\"><img src=\"../assets/organic/ethanol.svg\" alt=\"Expanded structural formula of ethanol\" style=\"display:block;max-width:100%;height:auto\" loading=\"lazy\"><figcaption>ethanol · Every bond is shown. Check four bonds at each carbon.</figcaption></figure><p class=\"eq\"><b>C<sub>2</sub>H<sub>5</sub>Br + KOH → C<sub>2</sub>H<sub>5</sub>OH + KBr</b></p><p><b>Conditions:</b> Boil with aqueous KOH.</p><p><b>What changes:</b> OH replaces Br. This is hydrolysis, not elimination.</p><p class=\"eq\"><b>C<sub>2</sub>H<sub>4</sub> + H<sub>2</sub>SO<sub>4</sub> → C<sub>2</sub>H<sub>5</sub>HSO<sub>4</sub></b></p><p><b>Conditions:</b> Conc. H2SO4 at 80°C under 30 atmospheres.</p><p><b>What changes:</b> Ethyl hydrogen sulphate forms.</p><p class=\"eq\"><b>C<sub>2</sub>H<sub>5</sub>HSO<sub>4</sub> + H<sub>2</sub>O → C<sub>2</sub>H<sub>5</sub>OH + H<sub>2</sub>SO<sub>4</sub></b></p><p><b>Conditions:</b> Hydrolyse with steam.</p><p><b>What changes:</b> Hydrolysis gives ethanol and regenerates the acid.</p><table class=\"cmp\"><tr><th>Question</th><th>Answer</th></tr><tr><td>Why use aqueous KOH to prepare ethanol?</td><td>OH replaces the halogen. Water-containing conditions favour hydrolysis.</td></tr><tr><td>Why not use hot alcoholic KOH?</td><td>It favours elimination, producing ethene instead.</td></tr></table><p class=\"eq\"><b>C<sub>2</sub>H<sub>5</sub>OH + 3O<sub>2</sub> → 2CO<sub>2</sub> + 3H<sub>2</sub>O</b></p><p><b>Conditions:</b> Ignite in excess oxygen.</p><p><b>What changes:</b> Complete combustion.</p><p class=\"eq\"><b>2C<sub>2</sub>H<sub>5</sub>OH + 2Na → 2C<sub>2</sub>H<sub>5</sub>ONa + H<sub>2</sub></b></p><p><b>Conditions:</b> Room temperature.</p><p><b>What changes:</b> H of the OH group is replaced by Na.</p><p class=\"eq\"><b>C<sub>2</sub>H<sub>5</sub>OH + [O] → CH<sub>3</sub>CHO + H<sub>2</sub>O</b></p><p><b>Conditions:</b> Acidified K2Cr2O7, controlled oxidation.</p><p><b>What changes:</b> Alcohol → aldehyde.</p><p class=\"eq\"><b>C<sub>2</sub>H<sub>5</sub>OH + 2[O] → CH<sub>3</sub>COOH + H<sub>2</sub>O</b></p><p><b>Conditions:</b> Warm with acidified K2Cr2O7.</p><p><b>What changes:</b> Further oxidation gives ethanoic acid.</p><p class=\"eq\"><b>C<sub>2</sub>H<sub>5</sub>OH → C<sub>2</sub>H<sub>4</sub> + H<sub>2</sub>O</b></p><p><b>Conditions:</b> Conc. H2SO4 at 170°C, or Al2O3 at 350°C.</p><p><b>What changes:</b> Dehydration removes H2O and creates a C=C bond.</p><p>At 140°C with excess ethanol and concentrated H₂SO₄: 2C₂H₅OH → C₂H₅OC₂H₅ + H₂O.</p><p>The product is ethoxyethane, also called diethyl ether. The summary’s “diethyl ethene” is a misprint.</p><p>Ethanol is a colourless, volatile, flammable liquid. It mixes with water and boils at about 78.3°C.</p><p>It is a solvent for gums, resins, oils and fats. It is used to manufacture ethanal and ethanoic acid.</p><p>Denatured alcohol: ethanol made unfit for drinking by adding substances such as pyridine or copper sulphate.</p><p>Spurious alcohol: the textbook term for undistilled alcohol containing methanol. Methanol can cause blindness or death.</p><p>Methylated spirit is ethanol denatured with methanol, in the traditional school definition.</p><p>Fermentation: C₁₂H₂₂O₁₁ + H₂O → C₆H₁₂O₆ + C₆H₁₂O₆, yeast invertase.</p><p>Glucose → 2C₂H₅OH + 2CO₂, yeast zymase. These are reference preparations in p.241.</p>", "acid": "<h3>Read –COOH as one functional group</h3><figure style=\"margin:12px 0\"><img src=\"../assets/organic/ethanoic-acid.svg\" alt=\"Expanded structural formula of ethanoic acid\" style=\"display:block;max-width:100%;height:auto\" loading=\"lazy\"><figcaption>ethanoic acid · Every bond is shown. Check four bonds at each carbon.</figcaption></figure><p class=\"eq\"><b>C<sub>2</sub>H<sub>5</sub>OH + 2[O] → CH<sub>3</sub>COOH + H<sub>2</sub>O</b></p><p><b>Conditions:</b> Warm with acidified K2Cr2O7.</p><p><b>What changes:</b> Further oxidation gives ethanoic acid.</p><p class=\"eq\"><b>CH<sub>3</sub>COOH + NaOH → CH<sub>3</sub>COONa + H<sub>2</sub>O</b></p><p><b>Conditions:</b> Aqueous alkali.</p><p><b>What changes:</b> Neutralisation gives sodium ethanoate and water.</p><p class=\"eq\"><b>2CH<sub>3</sub>COOH + Ca(OH)<sub>2</sub> → (CH<sub>3</sub>COO)<sub>2</sub>Ca + 2H<sub>2</sub>O</b></p><p><b>Conditions:</b> Aqueous alkali.</p><p><b>What changes:</b> Calcium ethanoate and water form.</p><p class=\"eq\"><b>CH<sub>3</sub>COOH + NH<sub>4</sub>OH → CH<sub>3</sub>COONH<sub>4</sub> + H<sub>2</sub>O</b></p><p><b>Conditions:</b> Ammonium hydroxide solution.</p><p><b>What changes:</b> Ammonium ethanoate and water form.</p><p class=\"eq\"><b>2CH<sub>3</sub>COOH + Na<sub>2</sub>CO<sub>3</sub> → 2CH<sub>3</sub>COONa + H<sub>2</sub>O + CO<sub>2</sub></b></p><p><b>Conditions:</b> Aqueous sodium carbonate.</p><p><b>What changes:</b> CO2 is evolved.</p><p class=\"eq\"><b>CH<sub>3</sub>COOH + NaHCO<sub>3</sub> → CH<sub>3</sub>COONa + H<sub>2</sub>O + CO<sub>2</sub></b></p><p><b>Conditions:</b> Aqueous sodium hydrogencarbonate.</p><p><b>What changes:</b> Effervescence of CO2 identifies an acid.</p><p class=\"eq\"><b>2CH<sub>3</sub>COOH + 2Na → 2CH<sub>3</sub>COONa + H<sub>2</sub></b></p><p><b>Conditions:</b> Room temperature.</p><p><b>What changes:</b> Acid + active metal → salt + hydrogen.</p><p class=\"eq\"><b>2CH<sub>3</sub>COOH + Mg → (CH<sub>3</sub>COO)<sub>2</sub>Mg + H<sub>2</sub></b></p><p><b>Conditions:</b> Room temperature.</p><p><b>What changes:</b> Magnesium ethanoate and hydrogen form.</p><p class=\"eq\"><b>CH<sub>3</sub>COOH + C<sub>2</sub>H<sub>5</sub>OH → CH<sub>3</sub>COOC<sub>2</sub>H<sub>5</sub> + H<sub>2</sub>O</b></p><p><b>Conditions:</b> Warm with concentrated H2SO4. The reaction is reversible.</p><p><b>What changes:</b> Ethanoic acid + ethanol → ethyl ethanoate + water.</p><table class=\"cmp\"><tr><th>Question</th><th>Answer</th></tr><tr><td>Why is ethanoic acid monocarboxylic?</td><td>Each molecule contains one carboxyl group.</td></tr><tr><td>Why add concentrated sulphuric acid during esterification?</td><td>It catalyses the reaction and removes water, favouring ester formation.</td></tr><tr><td>Why is pure ethanoic acid called glacial acetic acid?</td><td>It forms an ice-like crystalline mass on sufficient cooling, around 16.5–17°C.</td></tr><tr><td>Why is –COOH different from –CHO?</td><td>The carboxyl group has an OH attached to its carbonyl carbon. An aldehyde has H there.</td></tr></table><figure style=\"margin:12px 0\"><img src=\"../assets/organic/ethyl-ethanoate.svg\" alt=\"Expanded structural formula of ethyl ethanoate\" style=\"display:block;max-width:100%;height:auto\" loading=\"lazy\"><figcaption>ethyl ethanoate · Every bond is shown. Check four bonds at each carbon.</figcaption></figure><p>Ester naming has two parts: ethanol supplies ethyl. Ethanoic acid supplies ethanoate.</p><p>Ethanoic acid has a vinegar-like odour. It is colourless, water-miscible and boils at about 118°C.</p><p>It turns blue litmus red. A carbonate test gives CO₂. Neutral FeCl₃ gives a wine-red colour in the source test.</p><p>Uses: vinegar, food preservation, vinyl acetate, acetic anhydride, cellulose acetate, dyes and perfumes.</p><p>Reference reactions: hydrolysis of ethyl ethanoate gives ethanoic acid and ethanol.</p><p>3CH₃COOH + PCl₃ → 3CH₃COCl + H₃PO₃.</p><p>CH₃COOH + PCl₅ → CH₃COCl + POCl₃ + HCl.</p><p>2CH₃COOH → (CH₃CO)₂O + H₂O, P₂O₅ and heat.</p><p>CH₃COOH + 4[H] → C₂H₅OH + H₂O, LiAlH₄ in the source.</p>", "tests": "<h3>A test answer needs reagent + observation + conclusion</h3><table class=\"cmp\"><tr><th>Test</th><th>Ethane</th><th>Ethene</th><th>Ethyne</th></tr><tr><td>Bromine in CCl₄, without UV light</td><td>Brown colour remains</td><td>Brown colour disappears</td><td>Brown colour disappears</td></tr><tr><td>Cold dilute alkaline KMnO₄</td><td>Purple remains</td><td>Purple disappears</td><td>Purple disappears</td></tr><tr><td>Ammoniacal AgNO₃</td><td>No precipitate</td><td>No precipitate</td><td>White silver acetylide precipitate</td></tr><tr><td>Ammoniacal CuCl</td><td>No precipitate</td><td>No precipitate</td><td>Red copper acetylide precipitate</td></tr></table><p class=\"eq\"><b>C<sub>2</sub>H<sub>2</sub> + 2AgNO<sub>3</sub> + 2NH<sub>4</sub>OH → Ag<sub>2</sub>C<sub>2</sub> + 2NH<sub>4</sub>NO<sub>3</sub> + 2H<sub>2</sub>O</b></p><p><b>Conditions:</b> Ammoniacal silver nitrate, room temperature.</p><p><b>What changes:</b> White precipitate of silver acetylide.</p><p class=\"eq\"><b>C<sub>2</sub>H<sub>2</sub> + 2CuCl + 2NH<sub>4</sub>OH → Cu<sub>2</sub>C<sub>2</sub> + 2NH<sub>4</sub>Cl + 2H<sub>2</sub>O</b></p><p><b>Conditions:</b> Ammoniacal copper(I) chloride, room temperature.</p><p><b>What changes:</b> Red precipitate of copper acetylide. CuCl is correct, not CuCl2.</p><table class=\"cmp\"><tr><th>Question</th><th>Answer</th></tr><tr><td>Why does bromine not distinguish ethene from ethyne?</td><td>Both decolourise it. Use an acetylide test to distinguish these two.</td></tr><tr><td>Why specify no ultraviolet light with ethane and bromine?</td><td>Light can initiate substitution. The unsaturation test relies on addition without that condition.</td></tr><tr><td>Why not write CuCl₂ for the ethyne test?</td><td>The reagent is copper(I), or cuprous, chloride: CuCl. The summary and unit test contain this misprint.</td></tr></table><p>For ethanol versus ethanoic acid, use sodium hydrogencarbonate. Only the acid gives CO₂ effervescence.</p><p>The book lists decolourisation or a green change for KMnO₄. Cold dilute alkaline solution may form brown MnO₂.</p><p>Use disappearance of purple as the essential observation. Do not claim the organic product causes a green colour.</p><table class=\"cmp\"><tr><th>Compound</th><th>Main textbook uses</th></tr><tr><td>Methane</td><td>Domestic fuel; manufacture of methanol, formaldehyde, chloroform and carbon black</td></tr><tr><td>Ethane</td><td>Fuel; raw material for organic chemicals</td></tr><tr><td>Ethene</td><td>Fruit ripening; polyethylene; oxy-ethylene torch</td></tr><tr><td>Ethyne</td><td>Oxy-acetylene welding and cutting; manufacture of organic chemicals</td></tr><tr><td>Ethanol</td><td>Solvent; industrial feedstock; manufacture of ethanal and ethanoic acid</td></tr><tr><td>Ethanoic acid</td><td>Vinegar; preservation and flavouring; acetate-based chemicals</td></tr></table><p>The source lists acetylene for fruit ripening. Keep ethene as the appropriate fruit-ripening example in current teaching.</p>", "drawing": "<h3>Structure → name: use the same routine every time</h3><table class=\"cmp\"><tr><th>Carbon count</th><th>Root</th></tr><tr><td>1</td><td>meth-</td></tr><tr><td>2</td><td>eth-</td></tr><tr><td>3</td><td>prop-</td></tr><tr><td>4</td><td>but-</td></tr><tr><td>5</td><td>pent-</td></tr><tr><td>6</td><td>hex-</td></tr><tr><td>7</td><td>hept-</td></tr></table><ol><li>Select the longest continuous chain containing the relevant group or multiple bond.</li><li>Number from the end giving that group or multiple bond the lowest locant.</li><li>Locate each branch and halogen.</li><li>Combine the root, bond ending and functional-group ending.</li><li>Write substituents alphabetically. Use di-, tri- or tetra- for repeated substituents.</li></ol><figure style=\"margin:12px 0\"><img src=\"../assets/organic/4-methylpentan-2-ol.svg\" alt=\"Expanded structural formula of 4-methylpentan-2-ol\" style=\"display:block;max-width:100%;height:auto\" loading=\"lazy\"><figcaption>4-methylpentan-2-ol · Every bond is shown. Check four bonds at each carbon.</figcaption></figure><p>Five carbons give pentan-. The OH gets position 2. The methyl branch is at position 4.</p><p>Answer: 4-methylpentan-2-ol.</p><table class=\"cmp\"><tr><th>Question</th><th>Answer</th></tr><tr><td>Why not number from the methyl end?</td><td>The OH must receive the lower locant. Here its position is 2, not 4.</td></tr><tr><td>Why not select the visually straight horizontal line automatically?</td><td>The longest continuous chain can turn through a branch. Count connected carbons.</td></tr><tr><td>Why repeat the number in 2,2-dimethylpropane?</td><td>Both methyl groups attach to carbon 2. Each needs its locant.</td></tr></table><h3>Name → structure: reverse the routine</h3><ol><li>Draw the parent carbon chain.</li><li>Number the chain.</li><li>Insert the multiple bond or functional group.</li><li>Attach the named branches and halogens.</li><li>Add H atoms until each carbon has four bonds.</li></ol><figure style=\"margin:12px 0\"><img src=\"../assets/organic/2-chloro-3-methylbut-2-ene.svg\" alt=\"Expanded structural formula of 2-chloro-3-methylbut-2-ene\" style=\"display:block;max-width:100%;height:auto\" loading=\"lazy\"><figcaption>2-chloro-3-methylbut-2-ene · Every bond is shown. Check four bonds at each carbon.</figcaption></figure><p>This is the worked name-to-structure example on p.225.</p><p>Use commas between numbers and hyphens between numbers and words.</p><p>Modern names: butane, pentane, propanal, propanoic acid. Their carbon-1 position is implicit.</p><p>The source’s “1-butane”, “1-pentane” and redundant acid or aldehyde locants are unnecessary.</p><h3>Recognise the part that controls the family</h3><div class=\"exam\">★ <b>Learn this exactly:</b> Functional group — An atom, radical or bond which defines the structure of organic compounds &amp; confers characteristic properties to it.</div><table class=\"cmp\"><tr><th>Family</th><th>Structural feature</th><th>Name ending or prefix</th><th>Textbook examples</th></tr><tr><td>Alkene</td><td>C=C</td><td>-ene</td><td>Ethene / ethylene</td></tr><tr><td>Alkyne</td><td>C≡C</td><td>-yne</td><td>Ethyne / acetylene</td></tr><tr><td>Alcohol</td><td>–OH on a saturated carbon</td><td>-ol</td><td>Ethanol / ethyl alcohol</td></tr><tr><td>Aldehyde</td><td>–C(=O)H, written –CHO</td><td>-al</td><td>Ethanal / acetaldehyde</td></tr><tr><td>Carboxylic acid</td><td>–C(=O)OH, written –COOH</td><td>-oic acid</td><td>Ethanoic acid / acetic acid</td></tr><tr><td>Ketone</td><td>–C(=O)– within the chain</td><td>-one</td><td>Propanone / acetone</td></tr><tr><td>Ether</td><td>C–O–C</td><td>alkoxyalkane</td><td>Methoxymethane / dimethyl ether</td></tr><tr><td>Alkyl halide</td><td>–Cl, –Br, –I or –F</td><td>chloro-, bromo-, iodo-, fluoro-</td><td>Bromoethane / ethyl bromide</td></tr><tr><td>Ester</td><td>–C(=O)O–</td><td>alkyl alkanoate</td><td>Ethyl ethanoate / ethyl acetate</td></tr></table><figure style=\"margin:12px 0\"><img src=\"../assets/organic/ethanol.svg\" alt=\"Expanded structural formula of ethanol\" style=\"display:block;max-width:100%;height:auto\" loading=\"lazy\"><figcaption>ethanol · Every bond is shown. Check four bonds at each carbon.</figcaption></figure><figure style=\"margin:12px 0\"><img src=\"../assets/organic/ethanal.svg\" alt=\"Expanded structural formula of ethanal\" style=\"display:block;max-width:100%;height:auto\" loading=\"lazy\"><figcaption>ethanal · Every bond is shown. Check four bonds at each carbon.</figcaption></figure><figure style=\"margin:12px 0\"><img src=\"../assets/organic/ethanoic-acid.svg\" alt=\"Expanded structural formula of ethanoic acid\" style=\"display:block;max-width:100%;height:auto\" loading=\"lazy\"><figcaption>ethanoic acid · Every bond is shown. Check four bonds at each carbon.</figcaption></figure><p>Blue shading marks the characteristic group. In an alkane, there is no separate functional group.</p><p>An alkyl group forms when one H is removed from an alkane: CH₄ → CH₃–, methyl.</p><p>Other examples: ethyl C₂H₅–, propyl C₃H₇–, butyl C₄H₉–, pentyl C₅H₁₁–.</p><table class=\"cmp\"><tr><th>Question</th><th>Answer</th></tr><tr><td>Why is –COOH not simply an alcohol group?</td><td>Its OH belongs to a carboxyl group attached to a carbonyl carbon. The whole group determines acidic properties.</td></tr><tr><td>Why count the carbon in –CHO or –COOH?</td><td>That carbon belongs to the principal carbon chain.</td></tr><tr><td>Why not confuse an ether and an ester?</td><td>Both contain an oxygen bridge. An ester also contains C=O beside that bridge.</td></tr></table>"};
const ALL_CHAPTER=[{"id": "s-carbon", "title": "Carbon, bonds and representations", "ref": "p.220, 222, 246", "t": ["carbon"], "html": "<h3>Start by checking bonds, not memorising names</h3><p>Carbon has electronic configuration 2,4. It forms four covalent bonds.</p><p>Count a double bond twice. Count a triple bond three times.</p><div class=\"exam\">★ <b>Learn this exactly:</b> Catenation — Tendency of an element to form chains of identical atoms.</div><p>Strong carbon–carbon bonds permit straight, branched and closed chains.</p><p>Organic chemistry studies specific carbon compounds. Carbon oxides, carbonates, bicarbonates and metallic carbides are treated as inorganic.</p><table class=\"cmp\"><tr><th>Representation</th><th>What it tells you</th></tr><tr><td>Molecular formula</td><td>How many atoms of each element occur. C₂H₆ says two C and six H.</td></tr><tr><td>Structural formula</td><td>How atoms connect. CH₃–CH₃ shows the carbon–carbon bond.</td></tr><tr><td>Expanded structure</td><td>Each hydrogen and every bond are visible.</td></tr></table><figure style=\"margin:12px 0\"><img src=\"../assets/organic/ethane.svg\" alt=\"Expanded structural formula of ethane\" style=\"display:block;max-width:100%;height:auto\" loading=\"lazy\"><figcaption>ethane · Every bond is shown. Check four bonds at each carbon.</figcaption></figure><figure style=\"margin:12px 0\"><img src=\"../assets/organic/ethene.svg\" alt=\"Expanded structural formula of ethene\" style=\"display:block;max-width:100%;height:auto\" loading=\"lazy\"><figcaption>ethene · Every bond is shown. Check four bonds at each carbon.</figcaption></figure><figure style=\"margin:12px 0\"><img src=\"../assets/organic/ethyne.svg\" alt=\"Expanded structural formula of ethyne\" style=\"display:block;max-width:100%;height:auto\" loading=\"lazy\"><figcaption>ethyne · Every bond is shown. Check four bonds at each carbon.</figcaption></figure><table class=\"cmp\"><tr><th>Question</th><th>Answer</th></tr><tr><td>Why does ethene have fewer hydrogens than ethane?</td><td>The double bond uses two of each carbon’s four valencies. Each carbon therefore bonds to two hydrogens.</td></tr><tr><td>Why not give carbon five bonds?</td><td>Carbon is tetravalent in these compounds. The sum of its bond orders must be four.</td></tr><tr><td>Why can one molecular formula describe different compounds?</td><td>The same atoms can connect differently. Molecular formula does not specify connectivity.</td></tr></table><p>Open-chain compounds are aliphatic. Benzene is the cyclic example required by this source.</p><p>Benzene has six carbons in a ring, alternating double bonds in the school representation, and formula C₆H₆.</p><p>Wohler synthesised urea in 1828. This contradicted the vital-force theory.</p><table class=\"cmp\"><tr><th>Typical organic compound</th><th>Typical ionic inorganic compound</th></tr><tr><td>Covalent; often low melting and boiling points</td><td>Ionic; often high melting and boiling points</td></tr><tr><td>Often soluble in organic solvents; often poorly soluble in water</td><td>Often soluble in water</td></tr><tr><td>Usually poor electrical conductor</td><td>Conducts in molten or aqueous state, not as an ionic solid</td></tr></table><p>These comparisons are generalisations. Ethanol and ethanoic acid are water-soluble organic examples.</p>"}, {"id": "s-series", "title": "Homologous series and family formulae", "ref": "p.221, 227", "t": ["series"], "html": "<h3>One family pattern replaces many separate facts</h3><div class=\"exam\">★ <b>Learn this exactly:</b> A series of organic compounds which follow a regular structural pattern, in which the successive compounds differing by a ‘CH₂ group’.</div><p>Members share a functional group and general formula. Their chemical properties are similar.</p><p>Adjacent members differ by CH₂. Their relative molecular masses differ by 14.</p><p>Physical properties change gradually. Boiling point generally increases with molecular mass.</p><table class=\"cmp\"><tr><th>Family</th><th>General formula</th><th>First three members</th></tr><tr><td>Alkanes</td><td>CₙH₂ₙ₊₂, n ≥ 1</td><td>CH₄, C₂H₆, C₃H₈</td></tr><tr><td>Alkenes</td><td>CₙH₂ₙ, n ≥ 2</td><td>C₂H₄, C₃H₆, C₄H₈</td></tr><tr><td>Alkynes</td><td>CₙH₂ₙ₋₂, n ≥ 2</td><td>C₂H₂, C₃H₄, C₄H₆</td></tr><tr><td>Monohydric alcohols</td><td>CₙH₂ₙ₊₁OH</td><td>CH₃OH, C₂H₅OH, C₃H₇OH</td></tr></table><table class=\"cmp\"><tr><th>Question</th><th>Answer</th></tr><tr><td>Why is there no methene or methyne?</td><td>A carbon–carbon double or triple bond requires at least two carbon atoms.</td></tr><tr><td>Why do similar chemical properties recur?</td><td>Each member has the same functional group.</td></tr><tr><td>Why not identify every family from molecular formula alone?</td><td>Different structures can share a formula. CₙH₂ₙ can also describe a cycloalkane. Use the stated open-chain context.</td></tr></table><p>Relative molecular mass: multiply each atom count by its relative atomic mass. Add the results.</p><p>For C₅H₁₂: Mᵣ = 5 × 12 + 12 × 1 = 72. Vapour density = 72/2 = 36.</p>"}, {"id": "s-groups", "title": "Functional groups and common names", "ref": "p.222, 226", "t": ["groups"], "html": "<h3>Recognise the part that controls the family</h3><div class=\"exam\">★ <b>Learn this exactly:</b> Functional group — An atom, radical or bond which defines the structure of organic compounds &amp; confers characteristic properties to it.</div><table class=\"cmp\"><tr><th>Family</th><th>Structural feature</th><th>Name ending or prefix</th><th>Textbook examples</th></tr><tr><td>Alkene</td><td>C=C</td><td>-ene</td><td>Ethene / ethylene</td></tr><tr><td>Alkyne</td><td>C≡C</td><td>-yne</td><td>Ethyne / acetylene</td></tr><tr><td>Alcohol</td><td>–OH on a saturated carbon</td><td>-ol</td><td>Ethanol / ethyl alcohol</td></tr><tr><td>Aldehyde</td><td>–C(=O)H, written –CHO</td><td>-al</td><td>Ethanal / acetaldehyde</td></tr><tr><td>Carboxylic acid</td><td>–C(=O)OH, written –COOH</td><td>-oic acid</td><td>Ethanoic acid / acetic acid</td></tr><tr><td>Ketone</td><td>–C(=O)– within the chain</td><td>-one</td><td>Propanone / acetone</td></tr><tr><td>Ether</td><td>C–O–C</td><td>alkoxyalkane</td><td>Methoxymethane / dimethyl ether</td></tr><tr><td>Alkyl halide</td><td>–Cl, –Br, –I or –F</td><td>chloro-, bromo-, iodo-, fluoro-</td><td>Bromoethane / ethyl bromide</td></tr><tr><td>Ester</td><td>–C(=O)O–</td><td>alkyl alkanoate</td><td>Ethyl ethanoate / ethyl acetate</td></tr></table><figure style=\"margin:12px 0\"><img src=\"../assets/organic/ethanol.svg\" alt=\"Expanded structural formula of ethanol\" style=\"display:block;max-width:100%;height:auto\" loading=\"lazy\"><figcaption>ethanol · Every bond is shown. Check four bonds at each carbon.</figcaption></figure><figure style=\"margin:12px 0\"><img src=\"../assets/organic/ethanal.svg\" alt=\"Expanded structural formula of ethanal\" style=\"display:block;max-width:100%;height:auto\" loading=\"lazy\"><figcaption>ethanal · Every bond is shown. Check four bonds at each carbon.</figcaption></figure><figure style=\"margin:12px 0\"><img src=\"../assets/organic/ethanoic-acid.svg\" alt=\"Expanded structural formula of ethanoic acid\" style=\"display:block;max-width:100%;height:auto\" loading=\"lazy\"><figcaption>ethanoic acid · Every bond is shown. Check four bonds at each carbon.</figcaption></figure><p>Blue shading marks the characteristic group. In an alkane, there is no separate functional group.</p><p>An alkyl group forms when one H is removed from an alkane: CH₄ → CH₃–, methyl.</p><p>Other examples: ethyl C₂H₅–, propyl C₃H₇–, butyl C₄H₉–, pentyl C₅H₁₁–.</p><table class=\"cmp\"><tr><th>Question</th><th>Answer</th></tr><tr><td>Why is –COOH not simply an alcohol group?</td><td>Its OH belongs to a carboxyl group attached to a carbonyl carbon. The whole group determines acidic properties.</td></tr><tr><td>Why count the carbon in –CHO or –COOH?</td><td>That carbon belongs to the principal carbon chain.</td></tr><tr><td>Why not confuse an ether and an ester?</td><td>Both contain an oxygen bridge. An ester also contains C=O beside that bridge.</td></tr></table>"}, {"id": "s-naming", "title": "IUPAC: structure → name and name → structure", "ref": "p.224–226, 247–248", "t": ["naming"], "html": "<h3>Structure → name: use the same routine every time</h3><table class=\"cmp\"><tr><th>Carbon count</th><th>Root</th></tr><tr><td>1</td><td>meth-</td></tr><tr><td>2</td><td>eth-</td></tr><tr><td>3</td><td>prop-</td></tr><tr><td>4</td><td>but-</td></tr><tr><td>5</td><td>pent-</td></tr><tr><td>6</td><td>hex-</td></tr><tr><td>7</td><td>hept-</td></tr></table><ol><li>Select the longest continuous chain containing the relevant group or multiple bond.</li><li>Number from the end giving that group or multiple bond the lowest locant.</li><li>Locate each branch and halogen.</li><li>Combine the root, bond ending and functional-group ending.</li><li>Write substituents alphabetically. Use di-, tri- or tetra- for repeated substituents.</li></ol><figure style=\"margin:12px 0\"><img src=\"../assets/organic/4-methylpentan-2-ol.svg\" alt=\"Expanded structural formula of 4-methylpentan-2-ol\" style=\"display:block;max-width:100%;height:auto\" loading=\"lazy\"><figcaption>4-methylpentan-2-ol · Every bond is shown. Check four bonds at each carbon.</figcaption></figure><p>Five carbons give pentan-. The OH gets position 2. The methyl branch is at position 4.</p><p>Answer: 4-methylpentan-2-ol.</p><table class=\"cmp\"><tr><th>Question</th><th>Answer</th></tr><tr><td>Why not number from the methyl end?</td><td>The OH must receive the lower locant. Here its position is 2, not 4.</td></tr><tr><td>Why not select the visually straight horizontal line automatically?</td><td>The longest continuous chain can turn through a branch. Count connected carbons.</td></tr><tr><td>Why repeat the number in 2,2-dimethylpropane?</td><td>Both methyl groups attach to carbon 2. Each needs its locant.</td></tr></table><h3>Name → structure: reverse the routine</h3><ol><li>Draw the parent carbon chain.</li><li>Number the chain.</li><li>Insert the multiple bond or functional group.</li><li>Attach the named branches and halogens.</li><li>Add H atoms until each carbon has four bonds.</li></ol><figure style=\"margin:12px 0\"><img src=\"../assets/organic/2-chloro-3-methylbut-2-ene.svg\" alt=\"Expanded structural formula of 2-chloro-3-methylbut-2-ene\" style=\"display:block;max-width:100%;height:auto\" loading=\"lazy\"><figcaption>2-chloro-3-methylbut-2-ene · Every bond is shown. Check four bonds at each carbon.</figcaption></figure><p>This is the worked name-to-structure example on p.225.</p><p>Use commas between numbers and hyphens between numbers and words.</p><p>Modern names: butane, pentane, propanal, propanoic acid. Their carbon-1 position is implicit.</p><p>The source’s “1-butane”, “1-pentane” and redundant acid or aldehyde locants are unnecessary.</p>"}, {"id": "s-isomers", "title": "Chain and position isomerism", "ref": "p.223, 247–248", "t": ["isomers"], "html": "<h3>Same atom counts, different connections</h3><div class=\"exam\">★ <b>Learn this exactly:</b> Isomers are organic compounds having the same molecular formula but differing in molecular arrangement or in structural formula.</div><p>First compare molecular formulae. Then compare the carbon skeleton and group positions.</p><figure style=\"margin:12px 0\"><img src=\"../assets/organic/butane.svg\" alt=\"Expanded structural formula of butane\" style=\"display:block;max-width:100%;height:auto\" loading=\"lazy\"><figcaption>butane · Every bond is shown. Check four bonds at each carbon.</figcaption></figure><figure style=\"margin:12px 0\"><img src=\"../assets/organic/2-methylpropane.svg\" alt=\"Expanded structural formula of 2-methylpropane\" style=\"display:block;max-width:100%;height:auto\" loading=\"lazy\"><figcaption>2-methylpropane · Every bond is shown. Check four bonds at each carbon.</figcaption></figure><p>Both are C₄H₁₀. Different carbon skeletons give chain isomerism.</p><figure style=\"margin:12px 0\"><img src=\"../assets/organic/but-1-ene.svg\" alt=\"Expanded structural formula of but-1-ene\" style=\"display:block;max-width:100%;height:auto\" loading=\"lazy\"><figcaption>but-1-ene · Every bond is shown. Check four bonds at each carbon.</figcaption></figure><figure style=\"margin:12px 0\"><img src=\"../assets/organic/but-2-ene.svg\" alt=\"Expanded structural formula of but-2-ene\" style=\"display:block;max-width:100%;height:auto\" loading=\"lazy\"><figcaption>but-2-ene · Every bond is shown. Check four bonds at each carbon.</figcaption></figure><p>Both are C₄H₈. The same skeleton has its double bond at different positions.</p><p>That difference gives position isomerism.</p><table class=\"cmp\"><tr><th>Question</th><th>Answer</th></tr><tr><td>Why are rotating or reversing a drawing not new isomers?</td><td>The atoms remain connected in the same way.</td></tr><tr><td>Why do isomers within one series have similar chemical properties?</td><td>They have the same functional group. Their different structures can change physical properties.</td></tr><tr><td>Why are ethene and ethane not isomers?</td><td>Their molecular formulae differ: C₂H₄ and C₂H₆.</td></tr></table><p>Butane has two chain isomers. Pentane has three: pentane, 2-methylbutane and 2,2-dimethylpropane.</p><p>The butene structures in scope are but-1-ene, but-2-ene and 2-methylprop-1-ene.</p><p>The cis/trans drawings in the source are reference material. Core practice concerns chain and position isomerism.</p>"}, {"id": "s-alkanes", "title": "Methane and ethane: preparation and reactions", "ref": "p.228–231, 249", "t": ["alkanes"], "html": "<h3>Alkanes: remove a carboxyl carbon or replace a halogen</h3><p>Alkanes have only single carbon–carbon bonds. Their general formula is CₙH₂ₙ₊₂.</p><p>They are called paraffins because they have comparatively little chemical affinity.</p><p>Methane occurs in natural gas, marsh gas and fire damp. It is a greenhouse gas.</p><p class=\"eq\"><b>CH<sub>3</sub>COONa + NaOH → CH<sub>4</sub> + Na<sub>2</sub>CO<sub>3</sub></b></p><p><b>Conditions:</b> Heat with soda lime (NaOH + CaO).</p><p><b>What changes:</b> Remove the carboxyl carbon. Two-carbon salt gives one-carbon alkane.</p><p class=\"eq\"><b>C<sub>2</sub>H<sub>5</sub>COONa + NaOH → C<sub>2</sub>H<sub>6</sub> + Na<sub>2</sub>CO<sub>3</sub></b></p><p><b>Conditions:</b> Heat with soda lime.</p><p><b>What changes:</b> Three-carbon salt gives two-carbon alkane.</p><p class=\"eq\"><b>CH<sub>3</sub>I + 2[H] → CH<sub>4</sub> + HI</b></p><p><b>Conditions:</b> Zn/Cu couple in alcohol.</p><p><b>What changes:</b> Replace I with H: reduction of an alkyl halide.</p><p class=\"eq\"><b>C<sub>2</sub>H<sub>5</sub>Br + 2[H] → C<sub>2</sub>H<sub>6</sub> + HBr</b></p><p><b>Conditions:</b> Zn/Cu couple in alcohol.</p><p><b>What changes:</b> Replace Br with H.</p><table class=\"cmp\"><tr><th>Question</th><th>Answer</th></tr><tr><td>Why does sodium ethanoate give methane, not ethane?</td><td>The carboxyl carbon is removed as carbonate. Only one carbon remains in the hydrocarbon.</td></tr><tr><td>Why prefer soda lime to NaOH alone?</td><td>Soda lime is not deliquescent and does not attack the glass apparatus as NaOH alone does.</td></tr><tr><td>Why collect methane over water?</td><td>Methane is almost insoluble in water.</td></tr></table><h3>Substitution: replace H, retain the carbon skeleton</h3><p class=\"eq\"><b>CH<sub>4</sub> + Cl<sub>2</sub> → CH<sub>3</sub>Cl + HCl</b></p><p><b>Conditions:</b> Diffused sunlight or ultraviolet light.</p><p><b>What changes:</b> One H is replaced by Cl.</p><p class=\"eq\"><b>CH<sub>4</sub> + 4Cl<sub>2</sub> → CCl<sub>4</sub> + 4HCl</b></p><p><b>Conditions:</b> Excess chlorine, diffused sunlight.</p><p><b>What changes:</b> All four H atoms are replaced.</p><p class=\"eq\"><b>C<sub>2</sub>H<sub>6</sub> + 6Cl<sub>2</sub> → C<sub>2</sub>Cl<sub>6</sub> + 6HCl</b></p><p><b>Conditions:</b> Excess chlorine, diffused sunlight.</p><p><b>What changes:</b> All six H atoms are replaced.</p><p>Successive methane products: CH₃Cl → CH₂Cl₂ → CHCl₃ → CCl₄.</p><p>The products are chloromethane, dichloromethane, trichloromethane and tetrachloromethane.</p><p>Trichloromethane is chloroform. Tetrachloromethane is carbon tetrachloride.</p><h3>Oxidation: conditions decide the product</h3><p class=\"eq\"><b>CH<sub>4</sub> + 2O<sub>2</sub> → CO<sub>2</sub> + 2H<sub>2</sub>O</b></p><p><b>Conditions:</b> Ignite in excess oxygen.</p><p><b>What changes:</b> Complete combustion gives CO2 and water.</p><p class=\"eq\"><b>2C<sub>2</sub>H<sub>6</sub> + 7O<sub>2</sub> → 4CO<sub>2</sub> + 6H<sub>2</sub>O</b></p><p><b>Conditions:</b> Ignite in excess oxygen.</p><p><b>What changes:</b> Balance C, then H, then O.</p><p class=\"eq\"><b>2CH<sub>4</sub> + O<sub>2</sub> → 2CH<sub>3</sub>OH</b></p><p><b>Conditions:</b> Cu catalyst, 200°C, 100 atmospheres (source conditions).</p><p><b>What changes:</b> Controlled catalytic oxidation gives methanol.</p><p class=\"eq\"><b>2C<sub>2</sub>H<sub>6</sub> + O<sub>2</sub> → 2C<sub>2</sub>H<sub>5</sub>OH</b></p><p><b>Conditions:</b> Cu catalyst, 200°C, 100 atmospheres (source conditions).</p><p><b>What changes:</b> Controlled catalytic oxidation gives ethanol.</p><p class=\"eq\"><b>CH<sub>4</sub> + O<sub>2</sub> → HCHO + H<sub>2</sub>O</b></p><p><b>Conditions:</b> Molybdenum oxide catalyst, 350–500°C (source).</p><p><b>What changes:</b> Controlled catalytic oxidation gives methanal.</p><p class=\"eq\"><b>C<sub>2</sub>H<sub>6</sub> + O<sub>2</sub> → CH<sub>3</sub>CHO + H<sub>2</sub>O</b></p><p><b>Conditions:</b> Molybdenum oxide catalyst, 350–500°C (source).</p><p><b>What changes:</b> Controlled catalytic oxidation gives ethanal.</p><p>Limited oxygen can give carbon monoxide. Very limited oxygen can give carbon black.</p><p>2CH₄ + 3O₂ → 2CO + 4H₂O. 2C₂H₆ + 5O₂ → 4CO + 6H₂O.</p><p>2C₂H₆ + 3O₂ → 4C + 6H₂O.</p><p>The source’s direct acidified-dichromate oxidation of an alkane is a schematic pathway, not a standard laboratory preparation.</p><p>Use the specified catalytic conditions for alkane → alcohol. Use acidified dichromate for alcohol → aldehyde → acid.</p><p>Wurtz: 2CH₃I + 2Na → C₂H₆ + 2NaI, dry ether. It does not prepare methane.</p><p>Methane and ethane are colourless, odourless gases. They are nearly insoluble in water.</p>"}, {"id": "s-alkenes", "title": "Ethene: elimination, addition and polymerisation", "ref": "p.232–233, 250", "t": ["alkenes"], "html": "<h3>Addition: change C=C to C–C and attach new atoms</h3><figure style=\"margin:12px 0\"><img src=\"../assets/organic/ethene.svg\" alt=\"Expanded structural formula of ethene\" style=\"display:block;max-width:100%;height:auto\" loading=\"lazy\"><figcaption>ethene · Every bond is shown. Check four bonds at each carbon.</figcaption></figure><p class=\"eq\"><b>C<sub>2</sub>H<sub>5</sub>OH → C<sub>2</sub>H<sub>4</sub> + H<sub>2</sub>O</b></p><p><b>Conditions:</b> Conc. H2SO4 at 170°C, or Al2O3 at 350°C.</p><p><b>What changes:</b> Dehydration removes H2O and creates a C=C bond.</p><p class=\"eq\"><b>C<sub>2</sub>H<sub>5</sub>Br + KOH → C<sub>2</sub>H<sub>4</sub> + KBr + H<sub>2</sub>O</b></p><p><b>Conditions:</b> Hot concentrated alcoholic KOH.</p><p><b>What changes:</b> Dehydrohalogenation removes HBr.</p><p class=\"eq\"><b>C<sub>2</sub>H<sub>6</sub> → C<sub>2</sub>H<sub>4</sub> + H<sub>2</sub></b></p><p><b>Conditions:</b> About 500°C, silica–alumina catalyst, absence of air (source).</p><p><b>What changes:</b> Dehydrogenation removes H2.</p><table class=\"cmp\"><tr><th>Question</th><th>Answer</th></tr><tr><td>Why is the temperature 170°C important?</td><td>With concentrated H₂SO₄, this condition favours ethene. The source gives ether formation at 140°C.</td></tr><tr><td>Why alcoholic KOH rather than aqueous KOH?</td><td>Alcoholic KOH favours elimination to ethene. Aqueous KOH favours hydrolysis to ethanol.</td></tr><tr><td>Why pass prepared ethene through NaOH solution?</td><td>It removes acidic impurities, including CO₂ and SO₂.</td></tr></table><p class=\"eq\"><b>C<sub>2</sub>H<sub>4</sub> + H<sub>2</sub> → C<sub>2</sub>H<sub>6</sub></b></p><p><b>Conditions:</b> Nickel catalyst, about 300°C.</p><p><b>What changes:</b> Add one H to each carbon. Double bond becomes single.</p><p class=\"eq\"><b>C<sub>2</sub>H<sub>4</sub> + Cl<sub>2</sub> → C<sub>2</sub>H<sub>4</sub>Cl<sub>2</sub></b></p><p><b>Conditions:</b> Halogen in inert solvent CCl4, room temperature.</p><p><b>What changes:</b> Addition gives a 1,2-dihaloethane.</p><p class=\"eq\"><b>C<sub>2</sub>H<sub>4</sub> + Br<sub>2</sub> → C<sub>2</sub>H<sub>4</sub>Br<sub>2</sub></b></p><p><b>Conditions:</b> Halogen in inert solvent CCl4, room temperature.</p><p><b>What changes:</b> Addition gives a 1,2-dihaloethane.</p><p class=\"eq\"><b>C<sub>2</sub>H<sub>4</sub> + I<sub>2</sub> → C<sub>2</sub>H<sub>4</sub>I<sub>2</sub></b></p><p><b>Conditions:</b> Halogen in inert solvent CCl4, room temperature.</p><p><b>What changes:</b> Addition gives a 1,2-dihaloethane.</p><p class=\"eq\"><b>C<sub>2</sub>H<sub>4</sub> + HBr → C<sub>2</sub>H<sub>5</sub>Br</b></p><p><b>Conditions:</b> Room temperature (source).</p><p><b>What changes:</b> Hydrogen halide adds across the double bond.</p><p class=\"eq\"><b>C<sub>2</sub>H<sub>4</sub> + HCl → C<sub>2</sub>H<sub>5</sub>Cl</b></p><p><b>Conditions:</b> Room temperature (source).</p><p><b>What changes:</b> Hydrogen halide adds across the double bond.</p><p>Alkenes are called olefins: they form oily addition products with halogens.</p><p>They react readily at the multiple bond. Do not draw a carbon with five bonds after addition.</p><p>Cold dilute alkaline KMnO₄ oxidises ethene to ethane-1,2-diol: C₂H₄ + H₂O + [O] → C₂H₆O₂.</p><p>Ethene + ozone gives ethylene ozonide. This appears in the summary as reference chemistry.</p><p>Polymerisation joins many ethene molecules: n CH₂=CH₂ → (–CH₂–CH₂–)ₙ.</p><p>The source specifies high temperature, high pressure and a catalyst.</p><p>Ethene is colourless, slightly soluble in water and slightly lighter than air.</p><p>It is obtained by cracking petroleum hydrocarbons. It is used to ripen fruit and make polyethylene.</p>"}, {"id": "s-alkynes", "title": "Ethyne: preparation and two-stage addition", "ref": "p.236–239, 251", "t": ["alkynes"], "html": "<h3>Two additions can turn C≡C into C–C</h3><figure style=\"margin:12px 0\"><img src=\"../assets/organic/ethyne.svg\" alt=\"Expanded structural formula of ethyne\" style=\"display:block;max-width:100%;height:auto\" loading=\"lazy\"><figcaption>ethyne · Every bond is shown. Check four bonds at each carbon.</figcaption></figure><p class=\"eq\"><b>CaC<sub>2</sub> + 2H<sub>2</sub>O → C<sub>2</sub>H<sub>2</sub> + Ca(OH)<sub>2</sub></b></p><p><b>Conditions:</b> Add cold water dropwise at room temperature.</p><p><b>What changes:</b> Calcium carbide releases ethyne on reaction with water.</p><p class=\"eq\"><b>C<sub>2</sub>H<sub>4</sub>Br<sub>2</sub> + 2KOH → C<sub>2</sub>H<sub>2</sub> + 2KBr + 2H<sub>2</sub>O</b></p><p><b>Conditions:</b> Heat with concentrated alcoholic KOH (textbook route).</p><p><b>What changes:</b> Two HBr units are eliminated.</p><p class=\"eq\"><b>2CH<sub>4</sub> → C<sub>2</sub>H<sub>2</sub> + 3H<sub>2</sub></b></p><p><b>Conditions:</b> About 1500°C, electric arc, absence of air.</p><p><b>What changes:</b> Pyrolysis removes hydrogen and forms ethyne.</p><table class=\"cmp\"><tr><th>Question</th><th>Answer</th></tr><tr><td>Why add cold water dropwise to calcium carbide?</td><td>The reaction gives out heat. Gradual addition controls gas evolution.</td></tr><tr><td>Why collect ethyne over water?</td><td>It is only very slightly soluble in water.</td></tr><tr><td>Why distinguish one stage from two?</td><td>One addition gives an alkene. A second gives an alkane.</td></tr></table><p class=\"eq\"><b>C<sub>2</sub>H<sub>2</sub> + H<sub>2</sub> → C<sub>2</sub>H<sub>4</sub></b></p><p><b>Conditions:</b> Controlled partial hydrogenation. The source shows Ni and limited H2.</p><p><b>What changes:</b> One stage: triple bond becomes double. Continued reaction gives ethane.</p><p class=\"eq\"><b>C<sub>2</sub>H<sub>2</sub> + 2H<sub>2</sub> → C<sub>2</sub>H<sub>6</sub></b></p><p><b>Conditions:</b> Ni, about 300°C, excess hydrogen.</p><p><b>What changes:</b> Two stages add four H atoms.</p><p class=\"eq\"><b>C<sub>2</sub>H<sub>2</sub> + Cl<sub>2</sub> → C<sub>2</sub>H<sub>2</sub>Cl<sub>2</sub></b></p><p><b>Conditions:</b> Room temperature. Iodine addition is difficult (source).</p><p><b>What changes:</b> First stage gives a 1,2-dihaloethene.</p><p class=\"eq\"><b>C<sub>2</sub>H<sub>2</sub> + 2Cl<sub>2</sub> → C<sub>2</sub>H<sub>2</sub>Cl<sub>4</sub></b></p><p><b>Conditions:</b> Excess halogen in inert solvent CCl4.</p><p><b>What changes:</b> Two stages give 1,1,2,2-tetrahaloethane.</p><p class=\"eq\"><b>C<sub>2</sub>H<sub>2</sub> + Br<sub>2</sub> → C<sub>2</sub>H<sub>2</sub>Br<sub>2</sub></b></p><p><b>Conditions:</b> Room temperature. Iodine addition is difficult (source).</p><p><b>What changes:</b> First stage gives a 1,2-dihaloethene.</p><p class=\"eq\"><b>C<sub>2</sub>H<sub>2</sub> + 2Br<sub>2</sub> → C<sub>2</sub>H<sub>2</sub>Br<sub>4</sub></b></p><p><b>Conditions:</b> Excess halogen in inert solvent CCl4.</p><p><b>What changes:</b> Two stages give 1,1,2,2-tetrahaloethane.</p><p class=\"eq\"><b>C<sub>2</sub>H<sub>2</sub> + I<sub>2</sub> → C<sub>2</sub>H<sub>2</sub>I<sub>2</sub></b></p><p><b>Conditions:</b> Room temperature. Iodine addition is difficult (source).</p><p><b>What changes:</b> First stage gives a 1,2-dihaloethene.</p><p class=\"eq\"><b>C<sub>2</sub>H<sub>2</sub> + 2HBr → C<sub>2</sub>H<sub>4</sub>Br<sub>2</sub></b></p><p><b>Conditions:</b> Two successive additions, room temperature (source).</p><p><b>What changes:</b> Final product is 1,1-dihaloethane.</p><p class=\"eq\"><b>C<sub>2</sub>H<sub>2</sub> + 2HCl → C<sub>2</sub>H<sub>4</sub>Cl<sub>2</sub></b></p><p><b>Conditions:</b> Two successive additions, room temperature (source).</p><p><b>What changes:</b> Final product is 1,1-dihaloethane.</p><p>Ethyne is colourless. Impurities cause the characteristic garlic-like odour of commercial acetylene.</p><p>The source purification sequence uses water, then acidified K₂Cr₂O₇ to remove phosphine.</p><p>Ethyne burns: 2C₂H₂ + 5O₂ → 4CO₂ + 2H₂O.</p><p>Cold dilute alkaline KMnO₄ oxidises ethyne: C₂H₂ + 4[O] → (COOH)₂.</p><p>Ozonolysis produces an ozonide, then glyoxal, as reference material in the source.</p><p>The book’s double elimination using alcoholic KOH is an exam route. Full laboratory conversion normally requires stronger conditions.</p><p>The book’s statement that alkynes are always more reactive than alkenes is an oversimplification.</p><p>Core rule: both react at their multiple bonds. Exact relative reactivity depends on the reaction.</p>"}, {"id": "s-alcohol", "title": "Ethanol: hydrolysis, oxidation and dehydration", "ref": "p.240–241, 252", "t": ["alcohol"], "html": "<h3>One reagent choice changes the reaction path</h3><figure style=\"margin:12px 0\"><img src=\"../assets/organic/ethanol.svg\" alt=\"Expanded structural formula of ethanol\" style=\"display:block;max-width:100%;height:auto\" loading=\"lazy\"><figcaption>ethanol · Every bond is shown. Check four bonds at each carbon.</figcaption></figure><p class=\"eq\"><b>C<sub>2</sub>H<sub>5</sub>Br + KOH → C<sub>2</sub>H<sub>5</sub>OH + KBr</b></p><p><b>Conditions:</b> Boil with aqueous KOH.</p><p><b>What changes:</b> OH replaces Br. This is hydrolysis, not elimination.</p><p class=\"eq\"><b>C<sub>2</sub>H<sub>4</sub> + H<sub>2</sub>SO<sub>4</sub> → C<sub>2</sub>H<sub>5</sub>HSO<sub>4</sub></b></p><p><b>Conditions:</b> Conc. H2SO4 at 80°C under 30 atmospheres.</p><p><b>What changes:</b> Ethyl hydrogen sulphate forms.</p><p class=\"eq\"><b>C<sub>2</sub>H<sub>5</sub>HSO<sub>4</sub> + H<sub>2</sub>O → C<sub>2</sub>H<sub>5</sub>OH + H<sub>2</sub>SO<sub>4</sub></b></p><p><b>Conditions:</b> Hydrolyse with steam.</p><p><b>What changes:</b> Hydrolysis gives ethanol and regenerates the acid.</p><table class=\"cmp\"><tr><th>Question</th><th>Answer</th></tr><tr><td>Why use aqueous KOH to prepare ethanol?</td><td>OH replaces the halogen. Water-containing conditions favour hydrolysis.</td></tr><tr><td>Why not use hot alcoholic KOH?</td><td>It favours elimination, producing ethene instead.</td></tr></table><p class=\"eq\"><b>C<sub>2</sub>H<sub>5</sub>OH + 3O<sub>2</sub> → 2CO<sub>2</sub> + 3H<sub>2</sub>O</b></p><p><b>Conditions:</b> Ignite in excess oxygen.</p><p><b>What changes:</b> Complete combustion.</p><p class=\"eq\"><b>2C<sub>2</sub>H<sub>5</sub>OH + 2Na → 2C<sub>2</sub>H<sub>5</sub>ONa + H<sub>2</sub></b></p><p><b>Conditions:</b> Room temperature.</p><p><b>What changes:</b> H of the OH group is replaced by Na.</p><p class=\"eq\"><b>C<sub>2</sub>H<sub>5</sub>OH + [O] → CH<sub>3</sub>CHO + H<sub>2</sub>O</b></p><p><b>Conditions:</b> Acidified K2Cr2O7, controlled oxidation.</p><p><b>What changes:</b> Alcohol → aldehyde.</p><p class=\"eq\"><b>C<sub>2</sub>H<sub>5</sub>OH + 2[O] → CH<sub>3</sub>COOH + H<sub>2</sub>O</b></p><p><b>Conditions:</b> Warm with acidified K2Cr2O7.</p><p><b>What changes:</b> Further oxidation gives ethanoic acid.</p><p class=\"eq\"><b>C<sub>2</sub>H<sub>5</sub>OH → C<sub>2</sub>H<sub>4</sub> + H<sub>2</sub>O</b></p><p><b>Conditions:</b> Conc. H2SO4 at 170°C, or Al2O3 at 350°C.</p><p><b>What changes:</b> Dehydration removes H2O and creates a C=C bond.</p><p>At 140°C with excess ethanol and concentrated H₂SO₄: 2C₂H₅OH → C₂H₅OC₂H₅ + H₂O.</p><p>The product is ethoxyethane, also called diethyl ether. The summary’s “diethyl ethene” is a misprint.</p><p>Ethanol is a colourless, volatile, flammable liquid. It mixes with water and boils at about 78.3°C.</p><p>It is a solvent for gums, resins, oils and fats. It is used to manufacture ethanal and ethanoic acid.</p><p>Denatured alcohol: ethanol made unfit for drinking by adding substances such as pyridine or copper sulphate.</p><p>Spurious alcohol: the textbook term for undistilled alcohol containing methanol. Methanol can cause blindness or death.</p><p>Methylated spirit is ethanol denatured with methanol, in the traditional school definition.</p><p>Fermentation: C₁₂H₂₂O₁₁ + H₂O → C₆H₁₂O₆ + C₆H₁₂O₆, yeast invertase.</p><p>Glucose → 2C₂H₅OH + 2CO₂, yeast zymase. These are reference preparations in p.241.</p>"}, {"id": "s-acid", "title": "Ethanoic acid and esterification", "ref": "p.244–245, 252", "t": ["acid"], "html": "<h3>Read –COOH as one functional group</h3><figure style=\"margin:12px 0\"><img src=\"../assets/organic/ethanoic-acid.svg\" alt=\"Expanded structural formula of ethanoic acid\" style=\"display:block;max-width:100%;height:auto\" loading=\"lazy\"><figcaption>ethanoic acid · Every bond is shown. Check four bonds at each carbon.</figcaption></figure><p class=\"eq\"><b>C<sub>2</sub>H<sub>5</sub>OH + 2[O] → CH<sub>3</sub>COOH + H<sub>2</sub>O</b></p><p><b>Conditions:</b> Warm with acidified K2Cr2O7.</p><p><b>What changes:</b> Further oxidation gives ethanoic acid.</p><p class=\"eq\"><b>CH<sub>3</sub>COOH + NaOH → CH<sub>3</sub>COONa + H<sub>2</sub>O</b></p><p><b>Conditions:</b> Aqueous alkali.</p><p><b>What changes:</b> Neutralisation gives sodium ethanoate and water.</p><p class=\"eq\"><b>2CH<sub>3</sub>COOH + Ca(OH)<sub>2</sub> → (CH<sub>3</sub>COO)<sub>2</sub>Ca + 2H<sub>2</sub>O</b></p><p><b>Conditions:</b> Aqueous alkali.</p><p><b>What changes:</b> Calcium ethanoate and water form.</p><p class=\"eq\"><b>CH<sub>3</sub>COOH + NH<sub>4</sub>OH → CH<sub>3</sub>COONH<sub>4</sub> + H<sub>2</sub>O</b></p><p><b>Conditions:</b> Ammonium hydroxide solution.</p><p><b>What changes:</b> Ammonium ethanoate and water form.</p><p class=\"eq\"><b>2CH<sub>3</sub>COOH + Na<sub>2</sub>CO<sub>3</sub> → 2CH<sub>3</sub>COONa + H<sub>2</sub>O + CO<sub>2</sub></b></p><p><b>Conditions:</b> Aqueous sodium carbonate.</p><p><b>What changes:</b> CO2 is evolved.</p><p class=\"eq\"><b>CH<sub>3</sub>COOH + NaHCO<sub>3</sub> → CH<sub>3</sub>COONa + H<sub>2</sub>O + CO<sub>2</sub></b></p><p><b>Conditions:</b> Aqueous sodium hydrogencarbonate.</p><p><b>What changes:</b> Effervescence of CO2 identifies an acid.</p><p class=\"eq\"><b>2CH<sub>3</sub>COOH + 2Na → 2CH<sub>3</sub>COONa + H<sub>2</sub></b></p><p><b>Conditions:</b> Room temperature.</p><p><b>What changes:</b> Acid + active metal → salt + hydrogen.</p><p class=\"eq\"><b>2CH<sub>3</sub>COOH + Mg → (CH<sub>3</sub>COO)<sub>2</sub>Mg + H<sub>2</sub></b></p><p><b>Conditions:</b> Room temperature.</p><p><b>What changes:</b> Magnesium ethanoate and hydrogen form.</p><p class=\"eq\"><b>CH<sub>3</sub>COOH + C<sub>2</sub>H<sub>5</sub>OH → CH<sub>3</sub>COOC<sub>2</sub>H<sub>5</sub> + H<sub>2</sub>O</b></p><p><b>Conditions:</b> Warm with concentrated H2SO4. The reaction is reversible.</p><p><b>What changes:</b> Ethanoic acid + ethanol → ethyl ethanoate + water.</p><table class=\"cmp\"><tr><th>Question</th><th>Answer</th></tr><tr><td>Why is ethanoic acid monocarboxylic?</td><td>Each molecule contains one carboxyl group.</td></tr><tr><td>Why add concentrated sulphuric acid during esterification?</td><td>It catalyses the reaction and removes water, favouring ester formation.</td></tr><tr><td>Why is pure ethanoic acid called glacial acetic acid?</td><td>It forms an ice-like crystalline mass on sufficient cooling, around 16.5–17°C.</td></tr><tr><td>Why is –COOH different from –CHO?</td><td>The carboxyl group has an OH attached to its carbonyl carbon. An aldehyde has H there.</td></tr></table><figure style=\"margin:12px 0\"><img src=\"../assets/organic/ethyl-ethanoate.svg\" alt=\"Expanded structural formula of ethyl ethanoate\" style=\"display:block;max-width:100%;height:auto\" loading=\"lazy\"><figcaption>ethyl ethanoate · Every bond is shown. Check four bonds at each carbon.</figcaption></figure><p>Ester naming has two parts: ethanol supplies ethyl. Ethanoic acid supplies ethanoate.</p><p>Ethanoic acid has a vinegar-like odour. It is colourless, water-miscible and boils at about 118°C.</p><p>It turns blue litmus red. A carbonate test gives CO₂. Neutral FeCl₃ gives a wine-red colour in the source test.</p><p>Uses: vinegar, food preservation, vinyl acetate, acetic anhydride, cellulose acetate, dyes and perfumes.</p><p>Reference reactions: hydrolysis of ethyl ethanoate gives ethanoic acid and ethanol.</p><p>3CH₃COOH + PCl₃ → 3CH₃COCl + H₃PO₃.</p><p>CH₃COOH + PCl₅ → CH₃COCl + POCl₃ + HCl.</p><p>2CH₃COOH → (CH₃CO)₂O + H₂O, P₂O₅ and heat.</p><p>CH₃COOH + 4[H] → C₂H₅OH + H₂O, LiAlH₄ in the source.</p>"}, {"id": "s-tests", "title": "Observations, distinguishing tests and uses", "ref": "p.249–252", "t": ["tests"], "html": "<h3>A test answer needs reagent + observation + conclusion</h3><table class=\"cmp\"><tr><th>Test</th><th>Ethane</th><th>Ethene</th><th>Ethyne</th></tr><tr><td>Bromine in CCl₄, without UV light</td><td>Brown colour remains</td><td>Brown colour disappears</td><td>Brown colour disappears</td></tr><tr><td>Cold dilute alkaline KMnO₄</td><td>Purple remains</td><td>Purple disappears</td><td>Purple disappears</td></tr><tr><td>Ammoniacal AgNO₃</td><td>No precipitate</td><td>No precipitate</td><td>White silver acetylide precipitate</td></tr><tr><td>Ammoniacal CuCl</td><td>No precipitate</td><td>No precipitate</td><td>Red copper acetylide precipitate</td></tr></table><p class=\"eq\"><b>C<sub>2</sub>H<sub>2</sub> + 2AgNO<sub>3</sub> + 2NH<sub>4</sub>OH → Ag<sub>2</sub>C<sub>2</sub> + 2NH<sub>4</sub>NO<sub>3</sub> + 2H<sub>2</sub>O</b></p><p><b>Conditions:</b> Ammoniacal silver nitrate, room temperature.</p><p><b>What changes:</b> White precipitate of silver acetylide.</p><p class=\"eq\"><b>C<sub>2</sub>H<sub>2</sub> + 2CuCl + 2NH<sub>4</sub>OH → Cu<sub>2</sub>C<sub>2</sub> + 2NH<sub>4</sub>Cl + 2H<sub>2</sub>O</b></p><p><b>Conditions:</b> Ammoniacal copper(I) chloride, room temperature.</p><p><b>What changes:</b> Red precipitate of copper acetylide. CuCl is correct, not CuCl2.</p><table class=\"cmp\"><tr><th>Question</th><th>Answer</th></tr><tr><td>Why does bromine not distinguish ethene from ethyne?</td><td>Both decolourise it. Use an acetylide test to distinguish these two.</td></tr><tr><td>Why specify no ultraviolet light with ethane and bromine?</td><td>Light can initiate substitution. The unsaturation test relies on addition without that condition.</td></tr><tr><td>Why not write CuCl₂ for the ethyne test?</td><td>The reagent is copper(I), or cuprous, chloride: CuCl. The summary and unit test contain this misprint.</td></tr></table><p>For ethanol versus ethanoic acid, use sodium hydrogencarbonate. Only the acid gives CO₂ effervescence.</p><p>The book lists decolourisation or a green change for KMnO₄. Cold dilute alkaline solution may form brown MnO₂.</p><p>Use disappearance of purple as the essential observation. Do not claim the organic product causes a green colour.</p><table class=\"cmp\"><tr><th>Compound</th><th>Main textbook uses</th></tr><tr><td>Methane</td><td>Domestic fuel; manufacture of methanol, formaldehyde, chloroform and carbon black</td></tr><tr><td>Ethane</td><td>Fuel; raw material for organic chemicals</td></tr><tr><td>Ethene</td><td>Fruit ripening; polyethylene; oxy-ethylene torch</td></tr><tr><td>Ethyne</td><td>Oxy-acetylene welding and cutting; manufacture of organic chemicals</td></tr><tr><td>Ethanol</td><td>Solvent; industrial feedstock; manufacture of ethanal and ethanoic acid</td></tr><tr><td>Ethanoic acid</td><td>Vinegar; preservation and flavouring; acetate-based chemicals</td></tr></table><p>The source lists acetylene for fruit ripening. Keep ethene as the appropriate fruit-ripening example in current teaching.</p>"}, {"id": "s-drawing", "title": "Draw structures and mark functional groups", "ref": "p.226, 247–248", "t": ["drawing"], "html": "<h3>Structure → name: use the same routine every time</h3><table class=\"cmp\"><tr><th>Carbon count</th><th>Root</th></tr><tr><td>1</td><td>meth-</td></tr><tr><td>2</td><td>eth-</td></tr><tr><td>3</td><td>prop-</td></tr><tr><td>4</td><td>but-</td></tr><tr><td>5</td><td>pent-</td></tr><tr><td>6</td><td>hex-</td></tr><tr><td>7</td><td>hept-</td></tr></table><ol><li>Select the longest continuous chain containing the relevant group or multiple bond.</li><li>Number from the end giving that group or multiple bond the lowest locant.</li><li>Locate each branch and halogen.</li><li>Combine the root, bond ending and functional-group ending.</li><li>Write substituents alphabetically. Use di-, tri- or tetra- for repeated substituents.</li></ol><figure style=\"margin:12px 0\"><img src=\"../assets/organic/4-methylpentan-2-ol.svg\" alt=\"Expanded structural formula of 4-methylpentan-2-ol\" style=\"display:block;max-width:100%;height:auto\" loading=\"lazy\"><figcaption>4-methylpentan-2-ol · Every bond is shown. Check four bonds at each carbon.</figcaption></figure><p>Five carbons give pentan-. The OH gets position 2. The methyl branch is at position 4.</p><p>Answer: 4-methylpentan-2-ol.</p><table class=\"cmp\"><tr><th>Question</th><th>Answer</th></tr><tr><td>Why not number from the methyl end?</td><td>The OH must receive the lower locant. Here its position is 2, not 4.</td></tr><tr><td>Why not select the visually straight horizontal line automatically?</td><td>The longest continuous chain can turn through a branch. Count connected carbons.</td></tr><tr><td>Why repeat the number in 2,2-dimethylpropane?</td><td>Both methyl groups attach to carbon 2. Each needs its locant.</td></tr></table><h3>Name → structure: reverse the routine</h3><ol><li>Draw the parent carbon chain.</li><li>Number the chain.</li><li>Insert the multiple bond or functional group.</li><li>Attach the named branches and halogens.</li><li>Add H atoms until each carbon has four bonds.</li></ol><figure style=\"margin:12px 0\"><img src=\"../assets/organic/2-chloro-3-methylbut-2-ene.svg\" alt=\"Expanded structural formula of 2-chloro-3-methylbut-2-ene\" style=\"display:block;max-width:100%;height:auto\" loading=\"lazy\"><figcaption>2-chloro-3-methylbut-2-ene · Every bond is shown. Check four bonds at each carbon.</figcaption></figure><p>This is the worked name-to-structure example on p.225.</p><p>Use commas between numbers and hyphens between numbers and words.</p><p>Modern names: butane, pentane, propanal, propanoic acid. Their carbon-1 position is implicit.</p><p>The source’s “1-butane”, “1-pentane” and redundant acid or aldehyde locants are unnecessary.</p><h3>Recognise the part that controls the family</h3><div class=\"exam\">★ <b>Learn this exactly:</b> Functional group — An atom, radical or bond which defines the structure of organic compounds &amp; confers characteristic properties to it.</div><table class=\"cmp\"><tr><th>Family</th><th>Structural feature</th><th>Name ending or prefix</th><th>Textbook examples</th></tr><tr><td>Alkene</td><td>C=C</td><td>-ene</td><td>Ethene / ethylene</td></tr><tr><td>Alkyne</td><td>C≡C</td><td>-yne</td><td>Ethyne / acetylene</td></tr><tr><td>Alcohol</td><td>–OH on a saturated carbon</td><td>-ol</td><td>Ethanol / ethyl alcohol</td></tr><tr><td>Aldehyde</td><td>–C(=O)H, written –CHO</td><td>-al</td><td>Ethanal / acetaldehyde</td></tr><tr><td>Carboxylic acid</td><td>–C(=O)OH, written –COOH</td><td>-oic acid</td><td>Ethanoic acid / acetic acid</td></tr><tr><td>Ketone</td><td>–C(=O)– within the chain</td><td>-one</td><td>Propanone / acetone</td></tr><tr><td>Ether</td><td>C–O–C</td><td>alkoxyalkane</td><td>Methoxymethane / dimethyl ether</td></tr><tr><td>Alkyl halide</td><td>–Cl, –Br, –I or –F</td><td>chloro-, bromo-, iodo-, fluoro-</td><td>Bromoethane / ethyl bromide</td></tr><tr><td>Ester</td><td>–C(=O)O–</td><td>alkyl alkanoate</td><td>Ethyl ethanoate / ethyl acetate</td></tr></table><figure style=\"margin:12px 0\"><img src=\"../assets/organic/ethanol.svg\" alt=\"Expanded structural formula of ethanol\" style=\"display:block;max-width:100%;height:auto\" loading=\"lazy\"><figcaption>ethanol · Every bond is shown. Check four bonds at each carbon.</figcaption></figure><figure style=\"margin:12px 0\"><img src=\"../assets/organic/ethanal.svg\" alt=\"Expanded structural formula of ethanal\" style=\"display:block;max-width:100%;height:auto\" loading=\"lazy\"><figcaption>ethanal · Every bond is shown. Check four bonds at each carbon.</figcaption></figure><figure style=\"margin:12px 0\"><img src=\"../assets/organic/ethanoic-acid.svg\" alt=\"Expanded structural formula of ethanoic acid\" style=\"display:block;max-width:100%;height:auto\" loading=\"lazy\"><figcaption>ethanoic acid · Every bond is shown. Check four bonds at each carbon.</figcaption></figure><p>Blue shading marks the characteristic group. In an alkane, there is no separate functional group.</p><p>An alkyl group forms when one H is removed from an alkane: CH₄ → CH₃–, methyl.</p><p>Other examples: ethyl C₂H₅–, propyl C₃H₇–, butyl C₄H₉–, pentyl C₅H₁₁–.</p><table class=\"cmp\"><tr><th>Question</th><th>Answer</th></tr><tr><td>Why is –COOH not simply an alcohol group?</td><td>Its OH belongs to a carboxyl group attached to a carbonyl carbon. The whole group determines acidic properties.</td></tr><tr><td>Why count the carbon in –CHO or –COOH?</td><td>That carbon belongs to the principal carbon chain.</td></tr><tr><td>Why not confuse an ether and an ester?</td><td>Both contain an oxygen bridge. An ester also contains C=O beside that bridge.</td></tr></table>"}];
const TOPIC_SEC={"carbon": "s-carbon", "series": "s-series", "groups": "s-groups", "naming": "s-naming", "isomers": "s-isomers", "alkanes": "s-alkanes", "alkenes": "s-alkenes", "alkynes": "s-alkynes", "alcohol": "s-alcohol", "acid": "s-acid", "tests": "s-tests", "drawing": "s-drawing"};
